const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>new Date().toLocaleDateString('en-CA'), uid=()=>crypto.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2);
let state;try{state=JSON.parse(localStorage.getItem('forma-v1'))}catch{}state=state||{};
function normalizeProgress(input={}){const result={profile:{name:'',goal:'General fitness',level:'Beginner',days:3,duration:45,weight:'',height:'',age:'',gender:'Prefer not to say',sex:'Skip estimate',activity:1.45,equipment:['Bodyweight','Dumbbells','Bench'],diet:'All meals',allergies:[],...input.profile},sessions:[],foods:{},waters:{},weights:[],plans:{},targets:{calories:0,protein:0,carbs:0,fat:0},...input};result.profile={...{name:'',goal:'General fitness',level:'Beginner',days:3,duration:45,weight:'',height:'',age:'',gender:'Prefer not to say',sex:'Skip estimate',activity:1.45,equipment:['Bodyweight','Dumbbells','Bench'],diet:'All meals',allergies:[],...input.profile},...input.profile};return result}
state=normalizeProgress(state);let progressOwner='';const progressKey=()=>progressOwner?'forma-user-'+progressOwner:'forma-v1';const activeKey=()=>progressOwner?'forma-active-'+progressOwner:'forma-active';
let exercises=[],view='today',diaryDate=today(),recipeFilters={query:'',diet:'All meals',time:60},libraryFilters={query:'',muscle:'All muscles',equipment:'All equipment'},active=null,restEnd=0,recipePortion=1;
function save(){try{localStorage.setItem(progressKey(),JSON.stringify(state));$('.saved').textContent='● Saved on this device';if(typeof updatePlayerChrome==='function'&&exercises.length)updatePlayerChrome();window.formaAccount?.changed()}catch{$('.saved').textContent='Storage unavailable. Export your data.'}}function toast(t){$('#toast').textContent=t;$('#toast').style.opacity=1;clearTimeout(window.toastTimeout);window.toastTimeout=setTimeout(()=>$('#toast').style.opacity=0,2800)}
const navs=[['today','◫','Today'],['workout','⌁','Workouts'],['library','▤','Exercises'],['nutrition','◉','Nutrition'],['recipes','♧','Recipes'],['quests','✦','Quests'],['games','▦','Games'],['shop','◈','Shop'],['progress','↗','Progress'],['health','♡','Health apps'],['mascots','☺','My mascot'],['profile','⚙','My plan']];
function go(v){location.hash=v;if(view===v)render()}window.addEventListener('hashchange',()=>{toggleSidebar(false);stopMiniGame();view=location.hash.slice(1)||'today';render();window.scrollTo(0,0)});
function pageTitle(k,title,desc,action=''){return `<div class="topline"><div><div class="kicker">${k}</div><h1>${title}</h1><p class="muted">${desc}</p></div>${action||`<div class="date">◷ &nbsp; ${new Date().toLocaleDateString('en-GB',{weekday:'short',day:'numeric',month:'long'})}</div>`}</div>`}
function render(){if(!exercises.length)return;view=location.hash.slice(1)||'today';document.body.classList.toggle('in-setup',view==='setup');document.body.classList.toggle('training-active',view==='workout'&&!!active);$('#nav').innerHTML=buildNavigation();$('#profileName').textContent=state.profile.name||'Your space';$('#breadcrumb').textContent=({today:'Your daily overview',workout:'Training / Your workout',library:'Training / Exercise library',nutrition:'Fuel / Food diary',recipes:'Fuel / Recipe collection',progress:'Your progress',profile:'Your personal plan',guide:'Research & guidance',quests:'Your adventure / Quests & rewards',shop:'Basecamp / The reward shop',health:'Your wellbeing / Health apps',mascots:'Your player / Mascot collection',setup:'Your adventure / Guided setup',games:'Pocket arcade'})[view]||'Forma';const pages={health:healthApps,today:dashboard,workout:workouts,library:library,nutrition,recipes,profile,progress,guide,quests,shop,setup,healthApps,mascots,games};$('#app').innerHTML=(pages[view]||dashboard)();updatePlayerChrome();if(view==='workout'&&active)renderSession();applyProgressiveDisclosure();}
function totals(entries){return entries.reduce((a,e)=>({calories:a.calories+e.calories,protein:a.protein+e.protein,carbs:a.carbs+e.carbs,fat:a.fat+e.fat}),{calories:0,protein:0,carbs:0,fat:0})}function foods(){return state.foods[diaryDate]||[]}function n(v){return Math.round(v||0)}function available(e){return state.profile.equipment.includes(e.equipmentLabel)&&(![3,7].includes(e.key)||state.profile.equipment.includes('Bench'))}
function plan(index=0){let sets=state.profile.level==='Beginner'?2:3;let reps=state.profile.goal==='Build strength'&&state.profile.level!=='Beginner'?'6–8':'8–12';let patterns=index%2?['hinge','pull','push','squat','core']:['squat','push','pull','hinge','core'];if(state.profile.days>=4)patterns=index%2?['squat','hinge','core']:['push','pull','shoulders'];if(state.profile.duration>=50&&state.profile.days<4)patterns.splice(4,0,'shoulders');return patterns.map((pat,i)=>{let opts=exercises.filter(e=>e.pattern===pat&&available(e));let e=opts[(index+i)%Math.max(1,opts.length)];return e?{key:e.key,sets,reps:e.pattern==='core'?'20–30 sec':reps,rest:e.pattern==='core'?60:state.profile.goal==='Build strength'?150:90}:null}).filter(Boolean)}
function selectedPlan(){return state.plans[today()]||plan(state.sessions.length)}
function exerciseRow(p){let e=exercises[p.key];return `<div class="row"><div class="row-main"><img class="thumb" src="${e.images[0]}" alt="${esc(e.name)} starting position"><div><b>${e.name}</b><small>${p.sets} sets · ${p.reps} · ${e.equipmentLabel}</small></div></div><button class="circle-play" aria-label="View ${e.name} guide" onclick="showExercise(${e.key})">▶</button></div>`}
function dashboard(){let g=gameStats(),q=dailyQuests(),done=q.filter(q=>q.claimed).length,week=state.sessions.filter(s=>s.date>=weekStart()),food=(state.foods[today()]||[]).length;return `<div class="quiet-page-head"><div><span class="kicker">${new Date().toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'short'}).toUpperCase()}</span><h1>${state.profile.name?'Hey, '+esc(state.profile.name)+'.':'A little progress today.'}</h1><p class="muted">One mission at a time.</p></div><button class="mini-profile" onclick="go('mascots')">${mascotPortrait(currentMascot(),'tiny')}<span>Level ${g.level}<small>${g.into}/200 XP</small></span></button></div>${!state.onboarding?.complete?'<div class="setup-shortcut"><span>A few answers. Your own plan.</span><button class="btn small" onclick="beginSetup()">Set up my plan →</button></div>':''}<div class="today-layout"><section>${dailyMissionCard()}<div class="quiet-stats"><button onclick="go('progress')"><b>${week.length}<small> / ${state.profile.days}</small></b><span>Sessions this week</span></button><button onclick="go('nutrition')"><b>${food}</b><span>Meals logged today</span></button><button onclick="go('quests')"><b>${done}<small> / 3</small></b><span>Quests collected</span></button></div><details class="fold-panel"><summary><span>Your main goal<small>${esc(gaming().goal.name)}</small></span><span>Open map ↗</span></summary>${mainGoalPanel(true)}</details><details class="fold-panel"><summary><span>Your week<small>${(state.schedule?.days||suggestedDays(state.profile.days)).map(i=>['Sun','Mon','Tue','Wed','Thu','Fri','Sat'][i]).join(' · ')}</small></span><span>View schedule</span></summary><div class="fold-body"><div class="week">${weekDays()}</div><button class="text-button" onclick="beginSetup()">Adjust my routine ↗</button></div></details><details class="fold-panel"><summary><span>Health & recovery<small>Check-ins and imported data</small></span><span>View</span></summary><div class="fold-body">${healthSummary()}</div></details></section><section class="today-side"><div class="quiet-card"><div class="section-head"><h2>Daily quests</h2><button class="help-dot" aria-label="How daily quests work" onclick="showHelp('quests')">?</button></div>${q.map(compactQuest).join('')}<button class="text-button" onclick="go('quests')">Open quest board ↗</button></div><div class="arcade-teaser quiet-card"><span class="arcade-icon">✦</span><h3>A little play between sets.</h3><p>Two short games for your rest break.</p><button class="btn secondary" onclick="go('games')">Open pocket arcade ↗</button></div><div class="camp-shortcut quiet-card"><div>${mascotPortrait(currentMascot(),'tiny')}<span><b>${currentMascot().name}’s basecamp</b><small>◈ ${coinBalance()} coins · ${idleReady()} ready</small></span></div><button class="text-button" onclick="go('shop')">Visit camp & shop ↗</button></div></section></div>`}
function weekDays(){const base=new Date();base.setDate(base.getDate()-(base.getDay()+6)%7);return Array.from({length:7},(_,i)=>{let d=new Date(base);d.setDate(base.getDate()+i);let key=d.toLocaleDateString('en-CA');let done=state.sessions.some(s=>s.date===key);return `<div class="day ${key===today()?'active':''}">${['M','T','W','T','F','S','S'][i]}<b>${done?'✓':d.getDate()}</b><small>${done?'Done':key===today()?'Today':'·'}</small></div>`}).join('')}
function workouts(){return pageTitle('TRAIN WITH INTENTION','Your next good session.','Change the movement, choose the load, and go at your own pace.',`<button class="btn secondary" onclick="go('profile')">⚙ Adjust my plan</button>`)+`<div id="session">${active?'':planOverview()}</div>`}
function planOverview(){let p=selectedPlan();return `<div class="clean-workout-plan"><div class="quiet-card"><div class="section-head"><div><span class="kicker">YOUR NEXT SESSION</span><h2>${state.profile.days>=4?(state.sessions.length%2?'Lower body':'Upper body'):'Full body'}</h2><p class="muted">${p.length} movements · ${state.profile.duration} min planned</p></div><span class="pill">${state.profile.level}</span></div>${p.map((x,i)=>`<div class="row"><div class="row-main"><span class="muted">${i+1}</span><img class="thumb" src="${exercises[x.key].images[0]}" alt="${exercises[x.key].name}"><div><b>${exercises[x.key].name}</b><small>${x.sets} × ${x.reps} · ${x.rest}s rest</small></div></div><div class="plan-row-tools"><button class="text-button" onclick="swapExercise(${i})">Swap</button><button class="circle-play" aria-label="View ${exercises[x.key].name} guide" onclick="showExercise(${x.key})">▶</button></div></div>`).join('')}<div class="toolbar"><button class="btn" ${!p.length?'disabled':''} onclick="startSession()">Start workout →</button><button class="btn secondary" onclick="state.plans[today()]=plan(state.sessions.length+1);save();render()">Refresh ↻</button></div></div><details class="fold-panel"><summary><span>Before you start</span><span>Warm-up & weight guide</span></summary><div class="fold-body"><h3>Warm up</h3><p>Start with 5–8 minutes of easy movement and light practice sets.</p><h3>Choose your load ${inlineTip('weight')}</h3><p>Start light. Aim to finish each set with about 2–3 good reps left. Reduce the weight if control or form breaks down.</p><p>Stop a movement that causes sharp or worsening pain. Your profile measurements do not determine your safe lifting weight.</p></div></details></div>`}
function swapExercise(i){let p=active?active.plan:selectedPlan();let old=exercises[p[i].key];let opts=exercises.filter(e=>available(e)&&e.key!==old.key);openModal(`<span class="kicker">MAKE IT WORK FOR YOU</span><h2>Replace ${old.name}</h2><p class="muted">Same movement patterns appear first. Other choices change muscle coverage.</p>${opts.sort((a,b)=>(b.pattern===old.pattern)-(a.pattern===old.pattern)).map(e=>`<div class="row"><div class="row-main"><img class="thumb" src="${e.images[0]}" alt="${e.name}"><div><b>${e.name}</b><small>${e.equipmentLabel} · ${e.pattern}${e.pattern===old.pattern?' · same pattern':''}</small></div></div><button class="btn small secondary" onclick="applySwap(${i},${e.key})">Choose</button></div>`).join('')||'<p>No alternatives for your equipment. Update My plan.</p>'}`)}
function applySwap(i,k){if(active){active.plan[i].key=k;active.logs[i]=Array.from({length:active.plan[i].sets},()=>({kg:'',reps:'',rir:'',done:false}));persistActive()}else{let p=selectedPlan().map(x=>({...x}));p[i].key=k;state.plans[today()]=p;save()}closeModal();render();toast('Exercise replaced')}
function startSession(){if(!active){const p=selectedPlan();if(!p.length){go('profile');return}active={id:uid(),start:Date.now(),plan:p.map(x=>({...x})),logs:p.map(x=>Array.from({length:x.sets},()=>({kg:'',reps:'',rir:'',done:false})))};persistActive()}go('workout');render()}
function persistActive(){try{localStorage.setItem(activeKey(),JSON.stringify(active));window.formaAccount?.changed()}catch{toast('Storage unavailable. Keep this page open.')}}try{active=JSON.parse(localStorage.getItem('forma-active'))}catch{}
function renderSession(){if(!active||!$('#session'))return;let i=Math.min(active.currentIndex||0,active.plan.length-1),p=active.plan[i],e=exercises[p.key],count=active.logs.flat().filter(s=>s.done).length,total=active.logs.flat().length;$('#session').innerHTML=`<div class="focus-workout"><div class="focus-workout-top"><div><span class="kicker">SESSION IN PROGRESS</span><h2>${count} of ${total} sets logged</h2></div><button class="btn secondary small" onclick="pauseSession()">Pause</button></div><div class="exercise-dots" aria-label="Exercises in this session">${active.plan.map((p,j)=>`<button class="${i===j?'active':''} ${active.logs[j].every(s=>s.done)?'completed':''}" aria-label="Exercise ${j+1}: ${exercises[p.key].name}" onclick="selectSessionExercise(${j})">${active.logs[j].every(s=>s.done)?'✓':j+1}</button>`).join('')}</div><div class="quiet-card exercise-focus"><div class="exercise-focus-title"><img class="focus-exercise-image" src="${e.images[0]}" alt="${e.name} setup"><div><span class="muted">Exercise ${i+1} of ${active.plan.length}</span><h2>${e.name}</h2><p>${p.reps} · ${p.rest}s rest</p><div class="focus-tools"><button class="text-button" onclick="showExercise(${e.key})">Watch guide ▶</button><button class="text-button" onclick="swapExercise(${i})">Swap ↻</button></div></div></div><p class="focus-cue">${e.cue}</p><div class="set-row"><b>Set</b><span>Weight · kg ${inlineTip('weight')}</span><span>${e.pattern==='core'?'Hold · sec':'Reps'}</span><span>Reps left ${inlineTip('rir')}</span><span>Done</span></div>${active.logs[i].map((s,j)=>`<div class="set-row ${s.done?'done':''}" id="set-${i}-${j}"><b>${j+1}</b><input aria-label="${e.name} set ${j+1} weight in kg" type="number" min="0" max="1000" step="0.5" placeholder="0" value="${s.kg}" oninput="setValue(${i},${j},'kg',this.value)"><input aria-label="${e.name} set ${j+1} repetitions or seconds" type="number" min="1" max="600" placeholder="${e.pattern==='core'?20:10}" value="${s.reps}" oninput="setValue(${i},${j},'reps',this.value)"><input aria-label="Repetitions in reserve" type="number" min="0" max="10" placeholder="2–3" value="${s.rir}" oninput="setValue(${i},${j},'rir',this.value)"><button class="set-check" aria-label="Mark set ${j+1} complete" onclick="completeSet(${i},${j})">${s.done?'✓':'○'}</button></div>`).join('')}<div class="section-head" style="margin-top:13px"><button class="text-button" onclick="active.logs[${i}].push({kg:'',reps:'',rir:'',done:false});persistActive();renderSession()">+ Add set</button><small>${lastPerformance(e.key)}</small></div></div><div class="focus-workout-actions"><button class="btn secondary" ${i===0?'disabled':''} onclick="selectSessionExercise(${i-1})">← Previous</button><button class="btn" onclick="${i<active.plan.length-1?'selectSessionExercise('+(i+1)+')':'finishSession()'}">${i<active.plan.length-1?'Next exercise →':'Save session ✓'}</button></div><div class="focus-session-footer"><button class="text-button" onclick="finishSession()">Finish & save what I did</button><button class="text-button" onclick="discardSession()">Discard</button></div></div>`}
function selectSessionExercise(i){if(!active||i<0||i>=active.plan.length)return;active.currentIndex=i;persistActive();renderSession();window.scrollTo(0,0)}
function lastPerformance(k){let session=[...state.sessions].reverse().find(s=>s.plan.some(p=>p.key===k));if(!session)return 'First session';let ix=session.plan.findIndex(p=>p.key===k);let sets=session.logs[ix].filter(s=>s.done);return sets.length?`Last: ${sets[0].kg} kg × ${sets[0].reps}`:'No completed sets yet'}
function setValue(i,j,k,v){active.logs[i][j][k]=v;persistActive()}function completeSet(i,j){let s=active.logs[i][j];if(!s.done&&(s.kg===''||s.reps===''||!Number.isFinite(+s.kg)||+s.kg<0||+s.reps<=0||+s.reps>600||s.rir!==''&&(+s.rir<0||+s.rir>10))){toast('Enter a valid weight (0 for bodyweight) and reps or hold time.');return}s.done=!s.done;persistActive();renderSession();if(s.done)startRest(active.plan[i].rest)}
function pauseSession(){go('today');toast('Workout saved. Resume whenever you’re ready.')}function discardSession(){openModal('<h2>Discard this workout?</h2><p>Your unfinished sets will be removed.</p><button class="btn" onclick="active=null;persistActive();closeModal();render()">Discard workout</button> <button class="btn secondary" onclick="closeModal()">Keep training</button>')}
function finishSession(){let before=gameStats().level;let completed=active.logs.flat().filter(s=>s.done).length;if(!completed){toast('Complete at least one set before saving.');return}state.sessions.push({...active,date:today(),duration:Math.max(1,Math.round((Date.now()-active.start)/60000))});state.plans[today()]=undefined;save();active=null;persistActive();restEnd=0;$('.timer')?.remove();go('today');celebrate();setTimeout(()=>rewardNotice(before,`${completed} sets banked. Finish your daily check-out next.`),120)}
function startRest(sec){restEnd=Date.now()+sec*1000;$('.timer')?.remove();let d=document.createElement('div');d.className='timer';d.innerHTML='<span>REST<br><b id="countdown"></b></span><button onclick="restEnd+=30000">+30s</button><button onclick="openArcadePicker()">Play ✦</button><button onclick="restEnd=0;this.parentElement.remove()">Skip ×</button>';document.body.append(d);tick()}function tick(){document.body.classList.toggle('workout-rest',!!restEnd);if(!restEnd)return;let s=Math.max(0,Math.ceil((restEnd-Date.now())/1000));if($('#countdown'))$('#countdown').textContent=`${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`;if(!s){restEnd=0;$('.timer')?.remove();toast('Rest complete. Ready for your next set?')}}setInterval(tick,500);
function library(){let list=exercises.filter(e=>(e.name+' '+e.primaryMuscles.join(' ')).toLowerCase().includes(libraryFilters.query.toLowerCase())&&(libraryFilters.muscle==='All muscles'||e.primaryMuscles.includes(libraryFilters.muscle))&&(libraryFilters.equipment==='All equipment'||e.equipmentLabel===libraryFilters.equipment));return pageTitle('LEARN THE MOVEMENT','Good form comes first.','Position photos, step-by-step cues, and video tutorials for every exercise.')+`<div class="toolbar"><input aria-label="Search exercises" placeholder="Search exercise or muscle…" value="${esc(libraryFilters.query)}" oninput="libraryFilters.query=this.value;updateLibrary()"><select aria-label="Filter by muscle" onchange="libraryFilters.muscle=this.value;render()">${options(['All muscles',...new Set(exercises.flatMap(e=>e.primaryMuscles))],libraryFilters.muscle)}</select><select aria-label="Filter by equipment" onchange="libraryFilters.equipment=this.value;render()">${options(['All equipment',...new Set(exercises.map(e=>e.equipmentLabel))],libraryFilters.equipment)}</select></div><p class="muted" style="font-size:11px">${list.length} movements · Tap a card for the complete guide</p><div class="grid" id="exerciseGrid">${list.map(exerciseCard).join('')||'<div class="empty">No matching exercises. Try another filter.</div>'}</div>`}
function updateLibrary(){let pos=$('.toolbar input').selectionStart;render();$('.toolbar input').focus();$('.toolbar input').setSelectionRange(pos,pos)}
function exerciseCard(e){return `<article class="card exercise-card"><div class="image-wrap"><img loading="lazy" src="${e.images[0]}" alt="${e.name} starting position"><span class="pill">${e.primaryMuscles[0]}</span><button class="circle-play" onclick="showExercise(${e.key})" aria-label="Play ${e.name} tutorial">▶</button></div><div class="info"><h3>${e.name}</h3><small>${e.equipmentLabel} · ${e.level}</small><button class="btn secondary" onclick="showExercise(${e.key})">View movement guide ↗</button></div></article>`}
function openModal(html){$('#modalContent').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();$('#modal').scrollTop=0}function closeModal(){stopMiniGame();$('#modal').close();$('#modalContent').innerHTML='';if(['today','quests'].includes(view)&&exercises.length)render()}$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))closeModal()});$('#modal').addEventListener('cancel',()=>{stopMiniGame();$('#modalContent').innerHTML=''});
function showExercise(k){recordGuide(k);let e=exercises[k];openModal(`<span class="kicker">MOVEMENT LIBRARY / ${e.pattern.toUpperCase()}</span><h2 style="margin-top:10px">${e.name}</h2><p class="muted">${e.equipmentLabel} · ${e.primaryMuscles.join(', ')}${e.secondaryMuscles.length?' · also '+e.secondaryMuscles.join(', '):''}</p><div class="positions">${e.images.map((p,i)=>`<div><img src="${p}" alt="${e.name} ${i?'end':'start'} position"><small>${i?'02 / Movement position':'01 / Setup position'}</small></div>`).join('')}</div><div class="notice"><b>Your form cue</b><br>${e.cue}</div><h3>Watch the tutorial</h3><iframe class="video" title="${e.name} tutorial" src="https://www.youtube-nocookie.com/embed/${e.video}?rel=0&playsinline=1" referrerpolicy="strict-origin-when-cross-origin" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen></iframe><p style="font-size:11px" class="muted">Videos are played from YouTube and need internet access. If the player is unavailable, <a href="https://www.youtube.com/watch?v=${e.video}" target="_blank" rel="noopener">open the original tutorial ↗</a>. Match the equipment shown to your gym setup.</p><h3>Step by step</h3><ol class="steps">${e.instructions.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><p class="target-note"><b>Choosing the load:</b> start with a light practice set. Keep roughly 2–3 repetitions in reserve, move with control, and use a comfortable range of motion. For planks, end the hold before posture breaks down.</p><p class="muted" style="font-size:10px">Position images and base instructions: <a href="https://github.com/yuhonas/free-exercise-db" target="_blank" rel="noopener">Free Exercise DB (public domain)</a>. Tutorial: ${e.key===4?'Calisthenicmovement':e.key===1?'Bowflex':'ScottHermanFitness'}.</p>`)}
function options(arr,current){return arr.map(v=>`<option ${v==current?'selected':''} value="${esc(v)}">${esc(v)}</option>`).join('')}
