function mealTotals(m,portion=1){return m.ingredients.reduce((t,[id,g])=>{let f=foodDB[id];['calories','protein','carbs','fat'].forEach((k,i)=>t[k]+=f[i+1]*g/100*portion);return t},{calories:0,protein:0,carbs:0,fat:0})}
function suitable(m){return (state.profile.diet==='All meals'||(state.profile.diet==='Vegan'?m.diet==='Vegan':m.diet!=='Omnivore'))&&!m.allergens.some(a=>state.profile.allergies.includes(a))}
function recipeSmall(m){let t=mealTotals(m);return `<div class="row" style="padding:0"><div class="row-main"><img class="thumb" src="assets/${m.img}" alt="Meal inspiration"><div><b>${m.name}</b><small>~${n(t.calories)} kcal · ${n(t.protein)}g protein</small></div></div><button class="circle-play" aria-label="View recipe" onclick="showRecipe(${m.id})">↗</button></div>`}
function recipes(){let filtered=meals.filter(m=>suitable(m)&&(recipeFilters.diet==='All meals'||m.diet===recipeFilters.diet)&&m.time<=recipeFilters.time&&m.name.toLowerCase().includes(recipeFilters.query.toLowerCase()));let planned=state.mealPlan||[];return pageTitle('GOOD FOOD. LESS GUESSWORK.','Fuel the way you feel.','Simple recipes, flexible portions, and a meal plan that fits your day.',`<button class="btn secondary" onclick="showShopping()">Shopping list ↗</button>`)+`<div class="toolbar"><input aria-label="Search recipes" placeholder="Search meals…" value="${esc(recipeFilters.query)}" oninput="recipeFilters.query=this.value;updateRecipes()"><select aria-label="Diet filter" onchange="recipeFilters.diet=this.value;render()">${options(['All meals','Vegan','Vegetarian','Omnivore'],recipeFilters.diet)}</select><select aria-label="Preparation time" onchange="recipeFilters.time=+this.value;render()"><option value="60" ${recipeFilters.time===60?'selected':''}>Any prep time</option><option value="10" ${recipeFilters.time===10?'selected':''}>10 min or less</option><option value="20" ${recipeFilters.time===20?'selected':''}>20 min or less</option></select></div><div class="notice">Filtered by your saved diet and allergen preferences. Check ingredient labels and cross-contact yourself. Nutrition is an estimate; meal photos are illustrative.</div><div class="grid">${filtered.map(m=>{let t=mealTotals(m);return `<article class="card meal-card"><img class="meal-image" loading="lazy" src="assets/${m.img}" alt="Illustrative meal photograph"><div class="info"><div class="section-head"><span class="pill">${m.tag}</span><small>${m.time} min</small></div><h3>${m.name}</h3><div class="macro-line"><b>~${n(t.calories)} kcal</b><span>${n(t.protein)}g protein</span><span>${m.diet}</span></div><div class="meal-actions"><button class="btn small secondary" onclick="showRecipe(${m.id})">Recipe & portions ↗</button><button class="btn small" onclick="addToPlan(${m.id},1)">+ Plan</button></div></div></article>`}).join('')||'<div class="empty">No recipes match. Try adjusting filters or your saved dietary preferences.</div>'}</div><div class="card" style="margin-top:24px"><div class="section-head"><h2>Your meal plan</h2><button class="text-button" onclick="generateMealPlan()">Suggest a day ↻</button></div><p class="muted">Choose your meals, then log what you actually eat. A suggested day is a starting menu, not a complete nutrition prescription.</p>${planned.map((p,i)=>{let m=meals[p.id],t=mealTotals(m,p.portion);return `<div class="row"><div><b>${m.name}</b><small>${p.portion} serving(s) · ~${n(t.calories)} kcal</small></div><div><button class="text-button" onclick="logRecipe(${m.id},${p.portion})">Log eaten</button> &nbsp; <button class="text-button" aria-label="Remove planned meal" onclick="state.mealPlan.splice(${i},1);save();render()">×</button></div></div>`}).join('')||'<div class="empty">Your next meal starts here. Tap + Plan on a recipe.</div>'}${planned.length?`<p><b>Planned total: ~${n(planned.reduce((a,p)=>a+mealTotals(meals[p.id],p.portion).calories,0))} kcal</b></p><button class="btn secondary small" onclick="showShopping()">Build shopping list →</button>`:''}</div>`}
function updateRecipes(){let pos=$('.toolbar input').selectionStart;render();$('.toolbar input').focus();$('.toolbar input').setSelectionRange(pos,pos)}
function showRecipe(id){let m=meals[id];recipePortion=1;openModal(`<span class="kicker">${m.diet.toUpperCase()} / ${m.time} MINUTES</span><h2 style="margin-top:12px">${m.name}</h2><img class="meal-image" style="border-radius:12px;margin-top:18px;height:220px" src="assets/${m.img}" alt="Illustrative meal photograph"><div class="toolbar"><label>Number of servings<input id="portion" aria-label="Recipe servings" type="number" min="0.25" max="20" step="0.25" value="1" oninput="updatePortion(${id},this.value)"></label><div id="recipeMacros" style="align-self:center"></div></div><p class="muted" style="font-size:11px">Allergens: ${m.allergens.join(', ')}. Check product labels. Nutrition and photos are illustrative estimates.</p><h3>Ingredients</h3><ul class="steps" id="ingredients"></ul><small>Rice, meat and vegetables use cooked edible weights. Oats use dry weight.</small><h3 style="margin-top:20px">How to make it</h3><ol class="steps">${m.steps.map(s=>`<li>${s}</li>`).join('')}</ol><div class="toolbar"><button class="btn" onclick="logRecipe(${id},recipePortion)">Log this meal</button><button class="btn secondary" onclick="addToPlan(${id},recipePortion)">+ Add to meal plan</button></div>`);updatePortion(id,1)}
function updatePortion(id,v){recipePortion=Math.min(20,Math.max(.25,+v||1));$('#portion').value=recipePortion;let m=meals[id],t=mealTotals(m,recipePortion);$('#recipeMacros').innerHTML=`<b>~${n(t.calories)} kcal</b><small style="display:block">${n(t.protein)}g protein · ${n(t.carbs)}g carbs · ${n(t.fat)}g fat</small>`;$('#ingredients').innerHTML=m.ingredients.map(([i,g])=>`<li>${n(g*recipePortion)} g ${foodDB[i][0].toLowerCase()}</li>`).join('')}
function addToPlan(id,portion){state.mealPlan=state.mealPlan||[];state.mealPlan.push({id,portion});save();toast('Added to your meal plan');if(view==='recipes'&&!$('#modal').open)render()}
function generateMealPlan(){let candidates=meals.filter(suitable),picked=['Breakfast','Lunch','Dinner','Snack'].map(tag=>candidates.filter(m=>m.tag===tag)).filter(x=>x.length).map(x=>({id:x[Math.floor(Math.random()*x.length)].id,portion:1}));if(!picked.length){toast('No matching meals for your preferences.');return}state.mealPlan=picked;save();render();toast('A starter menu is ready. Adjust portions to your needs.')}
function logRecipe(id,portion){let m=meals[id];if(!suitable(m)){toast('This meal conflicts with your saved diet or allergen preferences.');return}addFood({id:uid(),name:m.name+' ('+portion+' serving'+(portion===1?'':'s')+')',meal:m.tag,...mealTotals(m,portion)});closeModal();toast(`Meal logged for ${diaryDate}`);if(view==='nutrition')render()}
function addFood(f){state.foods[diaryDate]=[...(state.foods[diaryDate]||[]),f];save()}
function showShopping(){let sum={};(state.mealPlan||[]).forEach(p=>meals[p.id].ingredients.forEach(([i,g])=>sum[i]=(sum[i]||0)+g*p.portion));openModal(`<span class="kicker">FROM YOUR MEAL PLAN</span><h2 style="margin-top:12px">A little shopping, sorted.</h2><p class="muted">Combined quantities for all planned servings. Cooked weights are meal quantities, not raw purchase weights. Check package yields when shopping.</p><div class="shopping">${Object.entries(sum).map(([i,g])=>`<label style="display:flex;align-items:center;gap:10px"><input type="checkbox">${n(g)} g ${foodDB[i][0]}</label>`).join('')||'Add some recipes to your meal plan first.'}</div>`)}
function nutrition(){let t=totals(foods()),tg=state.targets,water=state.waters[diaryDate]||0;return pageTitle('EVERYDAY NOURISHMENT','A little more in balance.','Log meals and portions. Notice patterns. Make room for food you enjoy.',`<input class="date-input" aria-label="Food diary date" type="date" value="${diaryDate}" max="${today()}" onchange="diaryDate=this.value;render()">`)+`<div class="card nutrition-summary"><div class="section-head"><h2>Your daily nutrition</h2><button class="text-button" onclick="showTargets()">Adjust targets ↗</button></div><div class="nutrition-inner"><div class="ring" style="--pct:${Math.min(100,t.calories/(tg.calories||2000)*100)}%"><span>${n(t.calories)}<small>kcal logged${tg.calories?' / '+tg.calories:' · no target set'}</small></span></div><div class="macro-block">${['protein','carbs','fat'].map((k,i)=>`<div><small>${['Protein','Carbohydrate','Fat'][i]}</small><b>${n(t[k])}<small> g${tg[k]?' / '+tg[k]:''}</small></b><div class="bar"><i style="width:${Math.min(100,t[k]/(tg[k]||100)*100)}%"></i></div></div>`).join('')}</div></div></div><div class="columns"><section><div class="section-head"><h2>Your food diary</h2><button class="btn small" onclick="showFoodForm()">+ Log food</button></div><div class="card">${['Breakfast','Lunch','Dinner','Snack'].map(group=>`<div class="section-head" style="margin-top:15px"><h3>${group}</h3><small>${n(foods().filter(f=>f.meal===group).reduce((a,f)=>a+f.calories,0))} kcal</small></div>${foods().filter(f=>f.meal===group).map(f=>`<div class="food-row"><div><b>${esc(f.name)}</b><small style="display:block">${n(f.protein)}g protein · ${n(f.carbs)}g carbs · ${n(f.fat)}g fat</small></div><span>${n(f.calories)} kcal</span><button aria-label="Delete ${esc(f.name)}" onclick="removeFood('${f.id}')">×</button></div>`).join('')||'<p class="muted" style="font-size:11px;padding-bottom:12px;border-bottom:1px solid var(--line)">Nothing logged yet.</p>'}`).join('')}</div></section><section><div class="card"><h3>Your water, at a glance.</h3><p class="muted">Log what you drink. Needs vary with heat, training and individual health.</p><div class="water"><b>${(water/1000).toFixed(2)} L</b><button class="btn small secondary" onclick="addWater(250)">+250 ml</button><button class="text-button" onclick="addWater(-250)">Undo glass</button></div></div><div class="card"><h3>Something good to eat?</h3><p class="muted">Explore simple meals with flexible portions and estimated nutrition.</p><button class="btn secondary" onclick="go('recipes')">Find a recipe ↗</button></div><div class="notice">Numbers are estimates, not a food score. For packaged products, enter the label values for the amount you actually eat. Restaurant meals vary with oil, sauces and portions.</div></section></div>`}
function addWater(v){let date=view==='nutrition'?diaryDate:today();state.waters[date]=Math.max(0,(state.waters[date]||0)+v);save();render();toast(v>0?'Water logged':'Water updated')}function removeFood(id){state.foods[diaryDate]=foods().filter(f=>f.id!==id);save();render()}
function showFoodForm(){openModal(`<span class="kicker">FOOD DIARY / ${diaryDate}</span><h2 style="margin-top:12px">What’s on your plate?</h2><div class="notice">Use a simple food estimate, or enter nutrition from your product label. Portions use grams of edible food.</div><form id="foodForm" onsubmit="submitFood(event)"><div class="fields"><label class="full">Food lookup<select id="foodSelect" onchange="fillFood()"><option value="">Custom food / nutrition label</option>${foodDB.map((f,i)=>`<option value="${i}">${f[0]}</option>`).join('')}</select></label><label>Amount · g<input id="foodGrams" type="number" min="1" max="5000" value="100" oninput="fillFood()"></label><label>Meal<select id="foodMeal">${options(['Breakfast','Lunch','Dinner','Snack'],'Snack')}</select></label><label class="full">Food name<input id="foodName" required maxlength="100" placeholder="e.g. Lunch from the café"></label><label>Calories · kcal<input id="fcalories" required type="number" min="0" max="10000" step="0.1"></label><label>Protein · g<input id="fprotein" required type="number" min="0" max="1000" step="0.1"></label><label>Carbohydrate · g<input id="fcarbs" required type="number" min="0" max="1000" step="0.1"></label><label>Fat · g<input id="ffat" required type="number" min="0" max="1000" step="0.1"></label></div><button class="btn" style="margin-top:20px" type="submit">Add to diary ✓</button></form>`)}
function fillFood(){let i=$('#foodSelect').value;if(i==='')return;let f=foodDB[+i],g=+$('#foodGrams').value;if(!g||g<0)return;$('#foodName').value=f[0]+' · '+g+'g';['calories','protein','carbs','fat'].forEach((k,j)=>$('#f'+k).value=(f[j+1]*g/100).toFixed(1))}function submitFood(e){e.preventDefault();addFood({id:uid(),name:$('#foodName').value,meal:$('#foodMeal').value,...Object.fromEntries(['calories','protein','carbs','fat'].map(k=>[k,+$('#f'+k).value]))});closeModal();render();toast('Food added to your diary')}
function estimate(){let p=state.profile;if(!p.weight||!p.height||!p.age||p.sex==='Skip estimate')return null;let bmr=10*p.weight+6.25*p.height-5*p.age+(p.sex==='Male equation'?5:-161);return {bmr:n(bmr),maintenance:n(bmr*+p.activity)}}
function showTargets(){let est=estimate(),t=state.targets;openModal(`<span class="kicker">FLEXIBLE DAILY TARGETS</span><h2 style="margin-top:12px">Your nutrition, your context.</h2><p class="muted">Targets are optional. You can log food without setting them. This app does not automatically prescribe a calorie deficit or add exercise calories back.</p>${est?`<div class="notice">Estimated maintenance: ~${est.maintenance} kcal/day. Mifflin–St Jeor estimates resting needs (${est.bmr} kcal), multiplied by your selected activity factor. This can differ substantially from your actual needs. It is not a weight-loss prescription.</div>`:'<div class="notice">Add adult age, height, weight, an equation option and activity level in My plan for an optional maintenance estimate.</div>'}<form onsubmit="saveTargets(event)"><div class="fields">${['calories','protein','carbs','fat'].map(k=>`<label>${k==='calories'?'Energy · kcal':k+' · g'}<input id="target-${k}" type="number" min="0" max="${k==='calories'?10000:1000}" value="${t[k]||0}"></label>`).join('')}</div><p class="target-note muted">Use 0 to leave a target unset. Choose targets with a qualified dietitian if you have medical or special nutritional needs. This estimate is for adults and is not designed for pregnancy or breastfeeding.</p><button class="btn" type="submit">Save targets</button> ${est?`<button class="btn secondary" type="button" onclick="$('#target-calories').value=${est.maintenance}">Use maintenance estimate</button>`:''}</form>`)}function saveTargets(e){e.preventDefault();let v=+$('#target-calories').value;if(v>0&&v<1500){toast('Forma supports tracking without a target. For low-energy diets, seek individualized guidance.');return}['calories','protein','carbs','fat'].forEach(k=>state.targets[k]=+$('#target-'+k).value);state.targetBasis='Custom';save();closeModal();render();toast('Targets updated')}
function profile(){let p=state.profile;return accountSummary()+'<div class="setup-shortcut"><span>✦ Want a plan made around you?</span><button class="btn small secondary" onclick="beginSetup()">Guided setup ↗</button></div>'+pageTitle('BUILT AROUND YOUR REAL LIFE','Make this space yours.','Your preferences shape the plan. Start with what you know; adjust as you go.')+`<form class="card form-section" onsubmit="saveProfile(event)"><h3>Your starting point</h3><div class="fields"><label>Name<input name="name" maxlength="35" value="${esc(p.name)}" placeholder="What should we call you?"></label><label>Goal<select name="goal">${options(['General fitness','Build muscle','Build strength','Fat loss & fitness'],p.goal)}</select></label><label>Experience<select name="level">${options(['Beginner','Intermediate','Experienced'],p.level)}</select></label><label>Strength sessions / week<select name="days">${options([2,3,4,5],p.days)}</select></label><label>Session length<select name="duration">${[30,45,60].map(v=>`<option value="${v}" ${v==p.duration?'selected':''}>${v} minutes</option>`).join('')}</select></label><label>Gender · optional<select name="gender">${options(['Prefer not to say','Woman','Man','Non-binary','Self-described'],p.gender)}</select></label><label>Body weight · kg · optional<input name="weight" type="number" min="25" max="350" step="0.1" value="${p.weight}"></label><label>Height · cm · optional<input name="height" type="number" min="100" max="230" value="${p.height}"></label><label>Age · adults only · optional<input name="age" type="number" min="18" max="100" value="${p.age}"></label><label>Energy estimate equation · optional<select name="sex">${options(['Skip estimate','Female equation','Male equation'],p.sex)}</select></label><label class="full">Usual activity · for optional energy estimate<select name="activity">${[[1.2,'Mostly seated, little activity'],[1.45,'Lightly active through the week'],[1.6,'Regular training and daily movement'],[1.75,'High daily activity and training']].map(([v,t])=>`<option value="${v}" ${v==p.activity?'selected':''}>${t}</option>`).join('')}</select></label></div><p class="target-note muted">Gender does not change exercise selection or calculate lifting loads. The optional equation setting is separate and only affects the maintenance-energy estimate. Choose Skip if it is not appropriate for you.</p><h3>What equipment can you use?</h3><div class="checks">${['Bodyweight','Dumbbells','Kettlebell','Barbell','Bench','Cable machine','Leg press'].map(e=>`<label><input type="checkbox" name="equipment" value="${e}" ${p.equipment.includes(e)?'checked':''}>${e}</label>`).join('')}</div><h3>Food preferences</h3><div class="fields"><label class="full">Meals to show<select name="diet">${options(['All meals','Vegetarian','Vegan'],p.diet)}</select></label></div><p class="muted" style="font-size:12px;margin-top:15px">Exclude these declared allergens:</p><div class="checks">${['Peanuts','Dairy','Egg','Soy','Fish','Wheat','Gluten'].map(a=>`<label><input type="checkbox" name="allergy" value="${a}" ${p.allergies.includes(a)?'checked':''}>${a}</label>`).join('')}</div><p class="target-note muted">Filters cover declared ingredients in the starter recipes. Check labels and preparation for other allergens and cross-contact.</p><div class="notice"><b>Start with a plan you can repeat.</b><br>For 2–3 days, use full-body sessions separated by recovery days. For 4–5 days, Forma alternates upper and lower sessions. An example 5-day week: upper / lower / rest / upper / lower / upper / rest; start the next week with lower.</div><button type="submit" class="btn">Save my plan ✓</button> <button type="button" class="btn secondary" onclick="showTargets()">Nutrition targets</button><p class="target-note muted">Save on this device, or sign in and enable cloud saving in Account & sync. Export a backup anytime.</p></form>`}
function saveProfile(e){e.preventDefault();let fd=new FormData(e.target),p=state.profile;['name','goal','level','gender','sex','diet'].forEach(k=>p[k]=fd.get(k));['days','duration','activity'].forEach(k=>p[k]=+fd.get(k));['weight','height','age'].forEach(k=>p[k]=fd.get(k)?+fd.get(k):'');p.equipment=fd.getAll('equipment');if(!p.equipment.includes('Bodyweight'))p.equipment.push('Bodyweight');p.allergies=fd.getAll('allergy');state.plans={};if(state.schedule?.days?.length!==p.days)state.schedule={days:suggestedDays(p.days)};save();toast('Your plan is updated');render()}
function progress(){let ss=state.sessions,sets=ss.reduce((a,s)=>a+s.logs.flat().filter(x=>x.done).length,0);return pageTitle('THE LONG VIEW','Look how far you’re going.','Real sessions, real progress. Your history starts with the first step.')+`<div class="stats"><div class="stat"><div class="stat-label">Sessions completed</div><div class="stat-value">${ss.length}</div><small>Every session you save</small></div><div class="stat"><div class="stat-label">Working sets</div><div class="stat-value">${sets}</div><small>Completed sets only</small></div><div class="stat"><div class="stat-label">Training time</div><div class="stat-value">${ss.reduce((a,s)=>a+s.duration,0)} <span>min</span></div><small>Elapsed session time, includes pauses</small></div><div class="stat"><div class="stat-label">Latest weight</div><div class="stat-value">${state.weights.length?state.weights.at(-1).weight:'–'} <span>kg</span></div><small>One data point in a bigger picture</small></div></div><div class="columns"><section><div class="card"><div class="section-head"><h2>Your training week</h2><span class="pill">Completed sessions</span></div><div class="chart">${Array.from({length:7},(_,i)=>{let d=new Date();d.setDate(d.getDate()-6+i);let key=d.toLocaleDateString('en-CA'),num=ss.filter(s=>s.date===key).length;return `<div><small>${num}</small><i style="height:${num?Math.min(115,num*55):3}px"></i><small>${d.toLocaleDateString('en-GB',{weekday:'short'})}</small></div>`}).join('')}</div></div><div class="card"><h2>Session history</h2>${ss.length?`<table class="history"><thead><tr><th>Date</th><th>Sets</th><th>Time</th><th>Details</th></tr></thead><tbody>${[...ss].reverse().map(s=>`<tr><td>${s.date}</td><td>${s.logs.flat().filter(x=>x.done).length}</td><td>${s.duration} min</td><td><button class="text-button" onclick="showHistory('${s.id}')">View ↗</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty">Your story starts with one session.<br><button class="btn secondary small" style="margin-top:16px" onclick="go(\'workout\')">Explore your workout</button></div>'}</div></section><section><div class="card"><h3>Check in with yourself.</h3><p class="muted">Body weight is optional. Strength, energy and consistency matter, too.</p><form onsubmit="logWeight(event)"><label>Weight · kg<input id="weightLog" type="number" required min="25" max="350" step="0.1" placeholder="e.g. 65.0"></label><button class="btn small" style="margin-top:13px">Save check-in</button></form>${state.weights.length?`<table class="history">${[...state.weights].reverse().slice(0,8).map(w=>`<tr><td>${w.date}</td><td>${w.weight} kg</td></tr>`).join('')}</table>`:''}</div><div class="card"><h3>Take your history with you.</h3><p class="muted">Download your workout logs, food diary and preferences as a backup.</p><button class="btn secondary small" onclick="exportData()">Export data ↓</button><label style="margin-top:15px">Restore a Forma backup<input type="file" accept="application/json,.json" onchange="importData(this.files[0])"></label></div></section></div>`}
function logWeight(e){e.preventDefault();state.weights.push({date:today(),weight:+$('#weightLog').value});save();render();toast('Check-in saved')}
function showHistory(id){let s=state.sessions.find(x=>x.id===id);openModal(`<h2>Session · ${s.date}</h2><p class="muted">${s.duration} minutes elapsed</p>${s.plan.map((p,i)=>`<h3 style="margin-top:22px">${exercises[p.key].name}</h3>${s.logs[i].filter(x=>x.done).map((x,j)=>`<div class="row"><b>Set ${j+1}</b><span>${x.kg} kg × ${x.reps}${exercises[p.key].pattern==='core'?' sec':' reps'}${x.rir!==''?' · '+x.rir+' reps left':''}</span></div>`).join('')||'<small>No completed sets</small>'}`).join('')}`)}
function exportData(){const blob=new Blob([JSON.stringify({...state,exportedAt:new Date().toISOString(),format:'forma-v1'},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='forma-backup-'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Your backup is ready')}
async function importData(file){if(!file)return;try{let x=JSON.parse(await file.text());if(x.format!=='forma-v1'||!Array.isArray(x.sessions)||!x.profile||!x.foods||!x.targets||!Array.isArray(x.weights))throw Error();openModal('<h2>Restore this backup?</h2><p>This replaces the profile and history on this device. Export your current data first if you want to keep it.</p><button id="restoreBackup" class="btn">Replace with backup</button> <button class="btn secondary" onclick="closeModal()">Cancel</button>');$('#restoreBackup').onclick=()=>{state=x;save();closeModal();render();toast('Backup restored')}}catch{toast('Please choose a valid Forma backup JSON file.')}}
function guide(){return pageTitle('A THOUGHTFUL FOUNDATION','Guidance you can look into.','The research, reference apps, and practical limits behind Forma.')+`<div class="research-grid"><div class="card"><span class="kicker">TRAINING</span><h3 style="margin-top:12px">Consistency before complexity.</h3><p>ACSM’s 2026 guidance emphasizes training major muscle groups at least twice weekly. Many equipment choices work, and training to failure is not required for general results.</p><p>Forma uses simple, editable templates with 2 working sets for beginners and 3 for other levels. These are starter templates, not a validated coaching algorithm. Build muscle uses moderate rep ranges; strength uses 6–8 reps for non-beginners and longer rests.</p><p><a target="_blank" rel="noopener" href="https://acsm.org/resistance-training-guidelines-update-2026/">ACSM resistance training guidance ↗</a></p><p><a target="_blank" rel="noopener" href="https://www.cdc.gov/physical-activity-basics/guidelines/adults.html">CDC adult physical activity guidelines ↗</a></p></div><div class="card"><span class="kicker">NUTRITION</span><h3 style="margin-top:12px">Estimates with context.</h3><p>Balanced meals include a variety of vegetables, fruit, grains, protein foods and dairy or fortified alternatives. Recipe portions are flexible; a generated menu is not guaranteed to meet your needs.</p><p>Food values in this starter collection are representative estimates, not a live USDA, TKPI, restaurant or barcode database. Use product labels or custom entries when precision matters. Calories and macros may differ because of rounding and food composition.</p><p><a target="_blank" rel="noopener" href="https://www.myplate.gov/eathealthy/budget/budget-weekly-meals">USDA MyPlate meal planning ↗</a></p><p><a target="_blank" rel="noopener" href="https://pubmed.ncbi.nlm.nih.gov/2305711/">Mifflin–St Jeor original research ↗</a></p><p>The optional energy estimate uses 10 × kg + 6.25 × cm − 5 × age, with +5 or −161, then an approximate activity multiplier. This is not a measured metabolic rate. Targets below 1,500 kcal are outside this starter tool’s scope; this is not an individual minimum requirement.</p></div><div class="card"><span class="kicker">SIMILAR APPS / FEATURES ADAPTED</span><h3 style="margin-top:12px">Familiar tools, one quiet space.</h3><p><a target="_blank" rel="noopener" href="https://fitbot.coach/">FitBot Coach</a>: one dashboard for training, recipes, food and progress.</p><p><a target="_blank" rel="noopener" href="https://fitbod.me/faqs/">Fitbod</a>: goal, equipment and experience settings; movement swaps and workout logs.</p><p><a target="_blank" rel="noopener" href="https://support.cronometer.com/hc/en-us/articles/360018171731-Diary-Overview">Cronometer</a>: dated food diary, portions and daily macro totals.</p><p><a target="_blank" rel="noopener" href="https://www.eatthismuch.com/meal-planner/">Eat This Much</a>: meal selection, dietary preferences and shopping lists.</p><p>Forma has original code and presentation. No proprietary app code, branding or food database was copied. It does not reproduce their AI coaching, recovery models, integrations, or full catalogues.</p></div><div class="card"><span class="kicker">MEDIA & DESIGN</span><h3 style="margin-top:12px">See it. Learn it. Make it yours.</h3><p>28 exercise guides include start and movement position photos from <a target="_blank" rel="noopener" href="https://github.com/yuhonas/free-exercise-db">Free Exercise DB</a>, plus practical cues and lightweight local WebM loops. Nineteen continuous-motion excerpts are adapted from Goulart via Wger under CC BY-SA 4.0. Nine position-photo loops are labeled as non-continuous motion. Each guide includes its media credits; optional longer tutorials open separately.</p><p>Meal and gym photos: Unsplash. Meal photos illustrate a meal style, not the exact calculated recipe.</p><p>Arcade design references: <a target="_blank" rel="noopener" href="https://styles.refero.design/style/95b472c5-fc07-46a8-a11f-c5432e290fcd">Duolingo</a> for tactile rewards, <a target="_blank" rel="noopener" href="https://styles.refero.design/style/3792d0ca-6c74-4667-a64d-76efe9f87076">Xbox</a> for mission hierarchy, and <a target="_blank" rel="noopener" href="https://styles.refero.design/style/7e21f6e1-deec-4bc4-a30e-f2c9d3320314">LEGO</a> for bold color blocking.</p></div></div><div class="card"><h3>How this version works</h3><p class="muted">Use Forma as a guest on this device, or sign in with Google and enable private Firebase cloud saving for your profile, active workout, diary, health records and progress. Export a backup anytime. Food-photo recognition, barcode scanning, live wearables and live coaching are not included.</p><p class="muted">This is an adult general-fitness planning and logging tool. It does not assess technique, diagnose pain, or replace individual guidance for injuries, pregnancy or health conditions. Stop exercise for chest pain, faintness or sharp pain and seek appropriate care.</p></div>`}
function gaming(){state.gaming=state.gaming||{};let g=state.gaming;for(let k of ['claims','guides','recovery','weeklyClaims','milestoneClaims','ledger','owned'])g[k]=g[k]||{};g.equipped=g.equipped||{theme:'volt',title:'PLAYER ONE',aura:'none'};g.idle=g.idle||{last:Date.now()};g.goal=g.goal||{id:'first-adventure',name:'Build my gym rhythm',metric:'sessions',target:12,base:0};g.customRewards=g.customRewards||[];g.redemptions=g.redemptions||[];for(let [key,c]of Object.entries(g.claims)){let id='daily:'+key;if(!g.ledger[id])g.ledger[id]={delta:c.id==='move'?20:10,label:'Daily quest',date:c.date||today()}}return g}
function gameStats(){let days={};for(let s of state.sessions){days[s.date]=(days[s.date]||0)+s.logs.flat().filter(x=>x.done).length}let setXP=Object.values(days).reduce((a,count)=>a+Math.min(count,10)*5+30,0);let claimed=Object.values(gaming().claims).reduce((a,c)=>a+(+c.xp||0),0);let bonus=Object.values(gaming().weeklyClaims).reduce((a,c)=>a+(+c.xp||0),0)+Object.values(gaming().milestoneClaims).reduce((a,c)=>a+(+c.xp||0),0);let xp=setXP+claimed+bonus,level=Math.floor(xp/200)+1;return {xp,level,into:xp%200,rank:level>=15?'Legend':level>=10?'Powerhouse':level>=5?'Momentum maker':level>=3?'Rising star':'The spark'}}
function dayCounts(){let date=today();return {session:state.sessions.some(s=>s.date===date),recovery:!!gaming().recovery[date],guide:(gaming().guides[date]||[]).length>0,food:(state.foods[date]||[]).length>0}}
function dailyQuests(){let d=dayCounts(),g=gaming();return [{id:'move',icon:'⚡',name:'Finish today’s mission',desc:'Warm up, save your session, then check out. Recovery days count too.',xp:40,done:(d.recovery&&!!missionState().restPlan&&!!missionState().energy)||(d.session&&!!missionState().warmup&&!!missionState().finish),action:'workout',cta:'Choose your mission'},{id:'learn',icon:'✦',name:'Practice one movement',desc:'Watch the guide, then try a light practice set.',xp:15,done:d.guide&&!!gaming().practice?.[today()]?.length,action:'library',cta:'Explore a movement'},{id:'fuel',icon:'♧',name:'Fuel your adventure',desc:'Log one meal. Every kind of meal counts.',xp:15,done:d.food,action:'nutrition',cta:'Log a meal'}].map(q=>({...q,claimed:!!g.claims[today()+':'+q.id]}))}
function questCard(q){return `<article class="quest-card ${q.claimed?'quest-claimed':q.done?'quest-ready':''}"><div class="quest-card-top"><span class="quest-symbol">${q.claimed?'✓':q.icon}</span><span class="xp-loot">+${q.xp} XP · ◈ ${q.id==='move'?20:10}</span></div><h3>${q.name}</h3><p>${q.desc}</p><button class="btn ${q.done&&!q.claimed?'':'secondary'}" ${q.claimed?'disabled':''} onclick="${q.done?`claimQuest('${q.id}')`:`go('${q.action}')`}">${q.claimed?'REWARD COLLECTED ✓':q.done?'CLAIM YOUR XP ✦':q.cta+' ↗'}</button>${q.id==='move'&&!q.done?'<button class="text-button recovery-link" onclick="recoveryCheckIn()">Recovery day? Check in here ☾</button>':''}</article>`}
function claimQuest(id){let q=dailyQuests().find(q=>q.id===id);if(!q||!q.done||q.claimed)return;let before=gameStats().level;gaming().claims[today()+':'+id]={xp:q.xp,date:today(),id};gaming();save();render();celebrate();rewardNotice(before,`+${q.xp} XP and +${q.id==='move'?20:10} coins! Quest complete.`)}
function recoveryCheckIn(){openModal(`<span class="game-label">RECOVERY QUEST / YOUR PACE</span><h2 style="margin-top:16px">REST. RESET. COME BACK STRONG.</h2><p class="muted">Today can be about sleep, comfortable movement, or simply taking a break. You can complete the daily movement quest with this recovery check-in.</p><div class="notice">Training and recovery share the same daily quest reward. You do not need to train to keep earning quest XP.</div><button class="btn" onclick="confirmRecovery()">SAVE RECOVERY CHECK-IN ☾</button>`)}
function confirmRecovery(){gaming().recovery[today()]=true;save();closeModal();go('quests');render();toast('Recovery logged. Your quest reward is ready to claim.');celebrate()}
function recordGuide(k){let g=gaming();g.guides[today()]=g.guides[today()]||[];if(!g.guides[today()].includes(k)){g.guides[today()].push(k);save()}}
function badges(){let ss=state.sessions,sets=ss.reduce((a,s)=>a+s.logs.flat().filter(l=>l.done).length,0),foodDays=Object.values(state.foods).filter(x=>x.length).length,g=gaming(),unique=new Set(Object.values(g.guides).flat()).size;return [{icon:'⚡',name:'First spark',desc:'Complete your first working set.',done:sets>=1,value:sets,goal:1},{icon:'⚑',name:'Mission complete',desc:'Save your first workout.',done:ss.length>=1,value:ss.length,goal:1},{icon:'✦',name:'Finding your rhythm',desc:'Save 5 workout sessions.',done:ss.length>=5,value:ss.length,goal:5},{icon:'♜',name:'Double digits',desc:'Save 10 workout sessions.',done:ss.length>=10,value:ss.length,goal:10},{icon:'◎',name:'Movement explorer',desc:'Explore 5 different exercise guides.',done:unique>=5,value:unique,goal:5},{icon:'♧',name:'Fuel journal',desc:'Log a meal on 5 different days.',done:foodDays>=5,value:foodDays,goal:5},{icon:'☾',name:'Recovery hero',desc:'Save a recovery-day check-in.',done:Object.keys(g.recovery).length>0,value:Object.keys(g.recovery).length,goal:1},{icon:'★',name:'Quest collector',desc:'Collect 10 daily quest rewards.',done:Object.keys(g.claims).length>=10,value:Object.keys(g.claims).length,goal:10}]}
let questTab='daily';function quests(){let tabs=[['daily','Daily'],['weekly','Weekly'],['milestones','Milestones'],['badges','Badges']];return pageTitle('YOUR ADVENTURE','A clear path to your next win.','Pick a quest. See the steps. Collect your reward.',`<button class="player-chip" onclick="showHelp('rewards')"><b>Level ${gameStats().level}</b><small>${gameStats().xp} XP</small></button>`)+`<div class="quest-tabs" role="tablist" aria-label="Quest categories">${tabs.map(([id,label])=>`<button role="tab" aria-selected="${questTab===id}" class="${questTab===id?'active':''}" onclick="questTab='${id}';render()">${label}</button>`).join('')}</div><section role="tabpanel" aria-label="${tabs.find(t=>t[0]===questTab)?.[1]||'Daily'} quests">${questTab==='daily'?`<div class="today-layout"><div>${dailyMissionCard()}</div><div class="quiet-card">${dailyQuests().map(compactQuest).join('')}<button class="text-button" onclick="showHelp('quests')">How to finish each quest ↗</button></div></div>`:questTab==='weekly'?weeklyPanel():questTab==='milestones'?mainGoalPanel(false):`<div class="badge-grid">${badges().map(b=>`<article class="badge-card ${b.done?'unlocked':'locked'}"><div class="badge-medal">${b.icon}</div><span class="badge-status">${b.done?'Unlocked':'In progress'}</span><h3>${b.name}</h3><p>${b.desc}</p><div class="bar"><i style="width:${Math.min(100,b.value/b.goal*100)}%"></i></div><small>${Math.min(b.value,b.goal)} / ${b.goal}</small></article>`).join('')}</div>`}</section>`}
function updatePlayerChrome(){applyCosmetics();let g=gameStats();$('.avatar').innerHTML=mascotPortrait(currentMascot(),'tiny');$('.saved').innerHTML=`<button class="wallet-mini" onclick="go('shop')" aria-label="Open shop, ${coinBalance()} coins">◈ ${coinBalance()}</button>`;$('.aside-bottom').innerHTML=`<div class="sidebar-level"><b>Level ${g.level}</b><small>${g.into} / 200 XP</small></div><div class="xp-track"><i style="width:${g.into/2}%"></i></div>`;renderAreaNavigation();updateAccountChrome()}
function celebrate(){if(window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;let box=document.createElement('div');box.className='confetti-burst';box.setAttribute('aria-hidden','true');for(let i=0;i<22;i++){let bit=document.createElement('i');bit.style.cssText=`--x:${Math.random()*100}vw;--r:${Math.random()*720}deg;--delay:${Math.random()*.2}s;background:${['#d8ff3e','#a994ff','#ff826a','#6fffe1'][i%4]}`;box.append(bit)}document.body.append(box);setTimeout(()=>box.remove(),1800)}
function rewardNotice(before,message){let g=gameStats();if(g.level>before)openModal(`<div class="level-up"><div class="game-label">NEW LEVEL UNLOCKED</div><div class="level-up-number">${g.level}</div><h2>LOOK AT YOU GO.</h2><p>${g.rank}. You earned every little step.</p><button class="btn" onclick="closeModal();go('quests')">KEEP THE ADVENTURE GOING ↗</button></div>`);else toast(message)}
function coinBalance(){return Object.values(gaming().ledger).reduce((a,t)=>a+(+t.delta||0),0)}
function coinTransaction(key,delta,label){let g=gaming();if(g.ledger[key])return false;if(delta<0&&coinBalance()<-delta)return false;g.ledger[key]={delta,label,date:today()};return true}
function metricValue(metric){if(metric==='sets')return state.sessions.reduce((a,s)=>a+s.logs.flat().filter(x=>x.done).length,0);if(metric==='guides')return new Set(Object.values(gaming().guides).flat()).size;return state.sessions.length}
function goalProgress(){let goal=gaming().goal;return {goal,value:Math.max(0,metricValue(goal.metric)-goal.base),unit:goal.metric==='sets'?'completed sets':goal.metric==='guides'?'movement guides':'saved workouts'}}
function goalMilestones(){let {goal,value}=goalProgress();return [25,50,75,100].map((pct,i)=>({id:goal.id+':'+pct,pct,target:Math.ceil(goal.target*pct/100),done:value>=Math.ceil(goal.target*pct/100),claimed:!!gaming().milestoneClaims[goal.id+':'+pct],coins:[25,35,50,80][i],xp:[20,25,35,60][i],name:['Find your footing','Build momentum','See it through','Main quest complete'][i]}))}
function mainGoalPanel(compact){let {goal,value,unit}=goalProgress(),pct=Math.min(100,value/goal.target*100),m=goalMilestones();return `<section class="main-goal-panel"><div class="section-head"><div><span class="game-label">MAIN QUEST / YOUR NORTH STAR</span><h2>${esc(goal.name)}</h2></div><button class="text-button" onclick="editMainGoal()">Edit goal ⚑</button></div><div class="goal-progress-line"><b>${Math.min(value,goal.target)}<span> / ${goal.target} ${unit}</span></b><span class="pill">${Math.floor(pct)}% complete</span></div><div class="xp-track goal-track"><i style="width:${pct}%"></i></div>${compact?`<div class="goal-markers">${m.map(x=>`<span class="${x.done?'done':''}">${x.claimed?'✓':x.done?'✦':'◇'} ${x.pct}%</span>`).join('')}</div><button class="text-button" onclick="go('quests')">${m.some(x=>x.done&&!x.claimed)?'Milestone reward ready! Collect it ↗':'Open your milestone map ↗'}</button>`:`<div class="milestone-path">${m.map((x,i)=>`<article class="milestone-node ${x.done?'reached':''}"><span class="milestone-orb">${x.claimed?'✓':x.done?'✦':i+1}</span><span class="game-label">CHAPTER ${i+1} / ${x.pct}%</span><h3>${x.name}</h3><p>${x.target} ${unit}</p><span class="milestone-loot">+${x.xp} XP · ◈ ${x.coins}</span><button class="btn small ${x.done&&!x.claimed?'':'secondary'}" ${!x.done||x.claimed?'disabled':''} onclick="claimMilestone('${x.id}')">${x.claimed?'COLLECTED ✓':x.done?'CLAIM REWARD':'KEEP GOING'}</button></article>`).join('')}</div>`}</section>`}
function editMainGoal(){let {goal}=goalProgress();openModal(`<span class="game-label">CHOOSE YOUR MAIN QUEST</span><h2 style="margin-top:15px">Give your adventure a direction.</h2><p class="muted">Pick a training habit you can measure. A new goal begins from your current progress, so future activity counts toward it.</p><form onsubmit="saveMainGoal(event)"><div class="fields"><label class="full">Main goal name<input id="mainGoalName" maxlength="65" required value="${esc(goal.name)}"></label><label>Track<select id="mainGoalMetric">${[['sessions','Workout sessions'],['sets','Completed working sets'],['guides','Different movement guides']].map(([v,t])=>`<option value="${v}" ${goal.metric===v?'selected':''}>${t}</option>`).join('')}</select></label><label>Target amount<input id="mainGoalTarget" type="number" required min="4" max="500" value="${goal.target}"></label></div><div class="notice">Your main quest measures habits, not a promised body outcome. Follow your training schedule and recovery needs. Changing this goal starts a new milestone map; coins already collected stay yours.</div><button class="btn" type="submit">START THIS MAIN QUEST ⚑</button></form>`)}
function saveMainGoal(e){e.preventDefault();let metric=$('#mainGoalMetric').value;if(metric==='guides'&&+$('#mainGoalTarget').value>exercises.length){toast('Choose up to '+exercises.length+' guides in this starter library.');return}gaming().goal={id:uid(),name:$('#mainGoalName').value,metric,target:+$('#mainGoalTarget').value,base:metricValue(metric)};save();closeModal();render();toast('New main quest started. Your next chapter is yours.');celebrate()}
function claimMilestone(id){let m=goalMilestones().find(m=>m.id===id);if(!m||!m.done||m.claimed)return;let before=gameStats().level;gaming().milestoneClaims[id]={xp:m.xp,date:today()};coinTransaction('milestone:'+id,m.coins,'Main quest milestone');save();render();celebrate();rewardNotice(before,`Milestone unlocked! +${m.xp} XP and +${m.coins} coins.`)}
function weekStart(){let d=new Date();d.setHours(12,0,0,0);d.setDate(d.getDate()-(d.getDay()+6)%7);return d.toLocaleDateString('en-CA')}
function weeklyQuests(){let week=weekStart(),end=today(),ss=state.sessions.filter(s=>s.date>=week&&s.date<=end),g=gaming(),keys=Object.keys(g.guides).filter(d=>d>=week&&d<=end),guides=new Set(keys.flatMap(d=>g.guides[d])).size,rest=Object.keys(g.recovery).filter(d=>d>=week&&d<=end).length,meals=Object.keys(state.foods).filter(d=>d>=week&&d<=end&&state.foods[d].length).length;return [{id:'training',icon:'⚑',name:'Keep your gym promises',desc:'Complete your planned strength sessions this week.',value:new Set(ss.map(s=>s.date)).size,target:state.profile.days,unit:'training days',xp:80,coins:50,action:'workout'},{id:'recovery',icon:'☾',name:'Make room for recovery',desc:'Save one recovery-day check-in this week.',value:rest,target:1,unit:'recovery days',xp:40,coins:25,action:'recovery'},{id:'technique',icon:'◎',name:'Build your movement toolkit',desc:'Explore three different exercise guides this week.',value:guides,target:3,unit:'movement guides',xp:40,coins:25,action:'library'},{id:'nutrition',icon:'♧',name:'Get to know your fuel',desc:'Log a meal on three different days this week.',value:meals,target:3,unit:'days logged',xp:40,coins:25,action:'nutrition'}].map(q=>({...q,key:week+':'+q.id,done:q.value>=q.target,claimed:!!g.weeklyClaims[week+':'+q.id]}))}
function weeklyPanel(){return `<section class="weekly-section"><div class="section-head"><div><span class="game-label">LONGER MISSIONS / BIGGER WINS</span><h2 style="margin-top:8px">YOUR WEEKLY QUESTS</h2></div><span class="pill">Week of ${weekStart()}</span></div><p class="muted">Weekly missions reset on Monday. Your training quest follows the session count in My plan. Multiple workouts on one day count as one training day.</p><div class="weekly-grid">${weeklyQuests().map(q=>`<article class="weekly-card ${q.claimed?'quest-claimed':''}"><div class="section-head"><span class="quest-symbol">${q.icon}</span><span class="xp-loot">+${q.xp} XP · ◈ ${q.coins}</span></div><h3>${q.name}</h3><p>${q.desc}</p><div class="bar"><i style="width:${Math.min(100,q.value/q.target*100)}%"></i></div><small>${Math.min(q.value,q.target)} / ${q.target} ${q.unit}</small><button class="btn small ${q.done&&!q.claimed?'':'secondary'}" ${q.claimed?'disabled':''} onclick="${q.done?`claimWeekly('${q.id}')`:q.action==='recovery'?'recoveryCheckIn()':`go('${q.action}')`}">${q.claimed?'COLLECTED ✓':q.done?'CLAIM WEEKLY REWARD ✦':'CONTINUE MISSION ↗'}</button></article>`).join('')}</div></section>`}
function claimWeekly(id){let q=weeklyQuests().find(q=>q.id===id);if(!q||!q.done||q.claimed)return;let before=gameStats().level;gaming().weeklyClaims[q.key]={xp:q.xp,date:today()};coinTransaction('weekly:'+q.key,q.coins,'Weekly quest');save();render();celebrate();rewardNotice(before,`Weekly mission complete! +${q.xp} XP and +${q.coins} coins.`)}
function idleReady(){return Math.max(0,Math.min(8,Math.floor((Date.now()-gaming().idle.last)/(3*60*60*1000))))}
function basecampPanel(){let ready=idleReady(),level=gameStats().level,stage=level>=10?'LEGEND’S HIDEOUT':level>=5?'MOMENTUM CAMP':'SPARK BASECAMP';return `<section class="basecamp-panel aura-${gaming().equipped.aura}"><div class="camp-character"><div class="camp-halo"></div><button class="companion-button" aria-label="Say hello to your gym companion" onclick="companionCheer()">${mascotPortrait(currentMascot(),'companion')}</button><span class="camp-spark spark-one">✦</span><span class="camp-spark spark-two">✦</span></div><div class="camp-copy"><span class="game-label">${stage} / LEVEL ${level}</span><h2>Your little corner of the adventure.</h2><p>${currentMascot().name} is holding down the fort. Basecamp earns 1 virtual coin every 3 hours, up to 8 while you’re away. No need to keep the app open.</p><div class="camp-controls"><button class="btn small ${ready?'':'secondary'}" ${ready?'':'disabled'} onclick="collectIdle()">${ready?'COLLECT ◈ '+ready+' COINS':'CAMP IS RECHARGING ☾'}</button><button class="text-button" onclick="go('shop')">Visit the shop ↗</button></div><small>${ready}/8 coins ready · Your camp changes titles at Levels 5 and 10.</small></div></section>`}
function collectIdle(){let amount=idleReady(),g=gaming();if(!amount)return;let key='idle:'+g.idle.last;if(!coinTransaction(key,amount,'Basecamp collection'))return;g.idle.last=Date.now();save();render();celebrate();toast(`Basecamp collected: +${amount} coins.`)}
const shopItems=[{id:'theme-cosmic',type:'theme',value:'cosmic',name:'Cosmic violet',desc:'Give your adventure a violet power-up.',cost:60,icon:'◐',color:'#ad93ff'},{id:'theme-coral',type:'theme',value:'coral',name:'Coral rush',desc:'A warmer, bolder accent for your HQ.',cost:60,icon:'☀',color:'#ff826a'},{id:'aura-stars',type:'aura',value:'stars',name:'Starlight aura',desc:'Sparkles drift around your basecamp companion.',cost:80,icon:'✦',color:'#e6ffa0'},{id:'aura-orbit',type:'aura',value:'orbit',name:'Power orbit',desc:'A glowing ring for your little training camp.',cost:100,icon:'◎',color:'#85e3d1'},{id:'title-spark',type:'title',value:'SPARK SEEKER',name:'Spark seeker',desc:'Equip a new player title on your dashboard.',cost:40,icon:'⚡',color:'#d8ff3e'},{id:'title-gym',type:'title',value:'GYM ADVENTURER',name:'Gym adventurer',desc:'For the hero who keeps coming back.',cost:90,icon:'⚑',color:'#ffbc8a'},{id:'title-captain',type:'title',value:'QUEST CAPTAIN',name:'Quest captain',desc:'A title worthy of your adventure board.',cost:150,icon:'♜',color:'#d7b0ff'}];
function shop(){let g=gaming(),balance=coinBalance();return pageTitle('YOUR HARD-EARNED LITTLE EXTRAS','Welcome to the reward shop.','Earn coins through quests. Pick a little something that makes the journey yours.',`<div class="coin-wallet"><span>◈</span><b>${balance}</b><small>COINS AVAILABLE</small></div>`)+basecampPanel()+`<div class="shop-tip"><span>✦</span><div><b>Play your way. Every purchase uses virtual coins.</b><p>Cosmetics change your app, not your performance. Personal rewards are reminders you redeem yourself. Nothing here charges money or orders physical goods.</p></div></div><div class="section-head"><h2>THE COSMETIC COLLECTION</h2><button class="text-button" onclick="resetCosmetics()">Restore original style ↻</button></div><div class="shop-grid">${shopItems.map(item=>{let owned=g.owned[item.id],equipped=g.equipped[item.type]===item.value;return `<article class="shop-card"><div class="shop-preview" style="--item-color:${item.color}"><span>${item.icon}</span><div class="price-tag">◈ ${item.cost}</div></div><div class="shop-card-copy"><span class="game-label">${item.type.toUpperCase()}</span><h3>${item.name}</h3><p>${item.desc}</p><button class="btn ${!owned&&balance<item.cost?'secondary':''}" ${equipped||!owned&&balance<item.cost?'disabled':''} onclick="${owned?`equipItem('${item.id}')`:`buyItem('${item.id}')`}">${equipped?'EQUIPPED ✓':owned?'EQUIP ↗':balance<item.cost?'NEED '+(item.cost-balance)+' MORE COINS':'BUY FOR ◈ '+item.cost}</button></div></article>`}).join('')}</div><div class="section-head" style="margin-top:30px"><h2>YOUR PERSONAL REWARD SHELF</h2><button class="btn small secondary" onclick="addPersonalReward()">+ Add reward</button></div><p class="muted">Name your own offline treat or experience, like a new gym playlist, a movie night, or a new training outfit. Coins only record your personal redemption.</p><div class="personal-rewards">${g.customRewards.map(r=>`<article class="card personal-reward"><div><span class="quest-symbol">★</span><h3>${esc(r.name)}</h3><small>Personal reward · ◈ ${r.cost}</small></div><button class="btn small ${balance<r.cost?'secondary':''}" ${balance<r.cost?'disabled':''} onclick="redeemPersonal('${r.id}')">${balance<r.cost?'SAVE UP':'REDEEM ◈ '+r.cost}</button></article>`).join('')||'<div class="empty">Your reward shelf is empty. Add something you’ll look forward to.</div>'}</div><div class="card" style="margin-top:25px"><h3>COIN JOURNAL</h3><p class="muted">Quests and collections earn coins. Purchases spend them.</p><div class="coin-history">${Object.values(g.ledger).slice(-12).reverse().map(t=>`<div class="row"><div><b>${esc(t.label)}</b><small>${t.date}</small></div><span class="coin-delta ${t.delta<0?'spent':''}">${t.delta>0?'+':''}${t.delta} ◈</span></div>`).join('')||'<p class="muted">Claim your first quest to earn coins.</p>'}</div></div>${g.redemptions.length?`<div class="card"><h3>YOUR REDEEMED REWARDS</h3>${g.redemptions.slice(-8).reverse().map(r=>`<div class="row"><div><b>${esc(r.name)}</b><small>${r.date} · ${r.cost} virtual coins</small></div><span class="pill">Redeemed ✓</span></div>`).join('')}</div>`:''}`}
function buyItem(id){let item=shopItems.find(x=>x.id===id),g=gaming();if(!item||g.owned[id])return;if(!coinTransaction('purchase:'+id,-item.cost,'Bought '+item.name)){toast('A few more quests will get you there.');return}g.owned[id]=true;g.equipped[item.type]=item.value;save();render();celebrate();toast(`${item.name} unlocked and equipped!`)}
function equipItem(id){let item=shopItems.find(x=>x.id===id);if(!item||!gaming().owned[id])return;gaming().equipped[item.type]=item.value;save();render();toast(item.name+' equipped')}
function resetCosmetics(){gaming().equipped={theme:'volt',title:'PLAYER ONE',aura:'none'};save();render();toast('Original style restored. Your purchases stay unlocked.')}
function applyCosmetics(){document.body.dataset.theme=gaming().equipped.theme;document.body.dataset.aura=gaming().equipped.aura}
function addPersonalReward(){openModal(`<span class="game-label">YOUR PERSONAL REWARD SHELF</span><h2 style="margin-top:15px">Something worth looking forward to.</h2><form onsubmit="savePersonalReward(event)"><div class="fields"><label class="full">Reward name<input id="personalRewardName" required maxlength="65" placeholder="e.g. A new gym playlist"></label><label class="full">Price · virtual coins<input id="personalRewardCost" type="number" required min="10" max="10000" value="100"></label></div><div class="notice">This is a personal reminder. Forma never charges money or buys the item for you. You decide how to fulfill it offline.</div><button class="btn" type="submit">ADD TO MY SHELF ★</button></form>`)}
function savePersonalReward(e){e.preventDefault();gaming().customRewards.push({id:uid(),name:$('#personalRewardName').value,cost:+$('#personalRewardCost').value});save();closeModal();render();toast('Your personal reward is on the shelf.')}
function redeemPersonal(id){let r=gaming().customRewards.find(x=>x.id===id);if(!r||coinBalance()<r.cost)return;openModal(`<span class="game-label">PERSONAL REWARD / VIRTUAL COINS</span><h2 style="margin-top:15px">${esc(r.name)}</h2><p class="muted">Redeem this reward for ${r.cost} virtual coins? This records it in your journal. You arrange the actual experience or item yourself.</p><button class="btn" id="confirmPersonalReward">REDEEM FOR ◈ ${r.cost}</button>`);$('#confirmPersonalReward').onclick=()=>{let g=gaming();if(!coinTransaction('redeem:'+uid(),-r.cost,'Redeemed '+r.name))return;g.redemptions.push({name:r.name,cost:r.cost,date:today()});save();closeModal();render();celebrate();toast('Reward redeemed. Enjoy your moment!')}}
function mobileMenu(){openModal(`<span class="game-label">YOUR ADVENTURE TOOLKIT</span><h2 style="margin-top:14px">Where to next?</h2><div class="mobile-menu-grid">${navs.map(([id,icon,label])=>`<button class="btn secondary" onclick="closeModal();go('${id}')"><span>${icon}</span>${label} ↗</button>`).join('')}</div>`)}
function companionCheer(){let notes=['One good session is a win. You’ve got this!','Recovery is part of the adventure, too.','Small steps. Strong foundations. Your companion believes in you!','Show up for yourself. The XP can wait.','Your next chapter starts with your next small step.'];toast(notes[Math.floor(Math.random()*notes.length)]);let img=$('.companion-art');if(img){img.classList.remove('panda-hop');void img.offsetWidth;img.classList.add('panda-hop');setTimeout(()=>img.classList.remove('panda-hop'),700)}}
const mascotOptions=[{id:'panda',name:'Pip',animal:'Panda',vibe:'Your steady, supportive teammate.',x:0,y:0},{id:'fox',name:'Ember',animal:'Fox',vibe:'Curious energy. Clever little wins.',x:50,y:0},{id:'cat',name:'Nova',animal:'Cat',vibe:'Cool focus. Your own pace.',x:100,y:0},{id:'axolotl',name:'Bubbles',animal:'Axolotl',vibe:'Tiny steps. Unstoppable joy.',x:0,y:100},{id:'tiger',name:'Rolo',animal:'Tiger',vibe:'Big heart. Brave beginnings.',x:50,y:100},{id:'rabbit',name:'Clover',animal:'Rabbit',vibe:'A little bounce for every day.',x:100,y:100}];
function currentMascot(){return mascotOptions.find(m=>m.id===gaming().mascot)||mascotOptions[0]}
function mascotPortrait(m,size='normal'){return `<span class="mascot-pfp ${size==='hero'?'hero-pfp':size==='companion'?'companion-art':size==='tiny'?'tiny-pfp':''}" role="img" aria-label="${m.name} the ${m.animal.toLowerCase()}" style="background-position:${m.x}% ${m.y}%"></span>`}
function mascotChoices(selected,callback){return `<div class="mascot-choice-grid">${mascotOptions.map(m=>`<button type="button" class="mascot-option ${selected===m.id?'chosen':''}" aria-pressed="${selected===m.id}" onclick="${callback}('${m.id}')">${mascotPortrait(m)}<b>${m.name}</b><small>${m.animal}</small><span class="pick-check">${selected===m.id?'✓':'+'}</span></button>`).join('')}</div>`}
function mascots(){let m=currentMascot();return pageTitle('YOUR PLAYER. YOUR PERSONALITY.','Meet your new gym crew.','Six cartoon companions. Same supportive energy. No character changes your workout difficulty.')+`<div class="mascot-intro card">${mascotPortrait(m,'companion')}<div><span class="game-label">YOUR CURRENT COMPANION</span><h2>${m.name} the ${m.animal.toLowerCase()}</h2><p class="muted">${m.vibe}</p><span class="pill">All six mascots are free to choose</span></div></div>${mascotChoices(m.id,'chooseMascot')}<div class="notice">Your choice appears on your player profile, dashboard and basecamp. All your XP, coins, purchases and progress stay with you.</div>`}
function chooseMascot(id){if(!mascotOptions.some(m=>m.id===id))return;gaming().mascot=id;save();render();toast(`${currentMascot().name} joined your adventure!`);celebrate()}
function suggestedDays(count){return ({2:[1,4],3:[1,3,5],4:[1,2,4,6],5:[1,2,4,5,6]})[count]||[1,3,5]}
let setupStep=0,setupDraft=null;
function makeSetupDraft(){return {profile:structuredClone(state.profile),mascot:currentMascot().id,schedule:state.schedule?.days||suggestedDays(state.profile.days),platform:state.health?.platform||'none',mealPlan:!(state.mealPlan?.length),keepGoal:state.sessions.length>0||!!state.onboarding?.complete,adults:false}}
function beginSetup(){setupDraft=makeSetupDraft();setupStep=0;go('setup');render()}
function skipSetup(){state.onboarding={...state.onboarding,dismissed:true};save();go('today');render()}
function completeSetup(){state.profile=structuredClone(setupDraft.profile);gaming().mascot=setupDraft.mascot;state.schedule={days:setupDraft.schedule};healthState().platform=setupDraft.platform;state.onboarding={complete:true,dismissed:false,completedAt:new Date().toISOString()};state.plans={};if(!setupDraft.keepGoal)gaming().goal={id:uid(),name:({ 'Build muscle':'Build my muscle-building rhythm','Build strength':'Build my strength foundation','Fat loss & fitness':'Build my fitness rhythm','General fitness':'Build my everyday strength'})[state.profile.goal],metric:'sessions',target:state.profile.days*4,base:state.sessions.length};state.plans[today()]=plan(state.sessions.length);if(setupDraft.mealPlan)prepareStarterMeals();save();setupDraft=null;go('today');render();celebrate();toast('Your plan is ready. Your adventure starts here.')}
function prepareStarterMeals(){state.mealPlan=['Breakfast','Lunch','Dinner','Snack'].map(tag=>meals.find(m=>m.tag===tag&&suitable(m))).filter(Boolean).map(m=>({id:m.id,portion:1}))}
function coachPanel(){let days=state.schedule?.days||suggestedDays(state.profile.days),train=days.includes(new Date().getDay()),missing=['squat','hinge','push','pull'].filter(p=>!exercises.some(e=>e.pattern===p&&available(e)));return `${!state.onboarding?.complete?'<div class="setup-shortcut"><span>✦ A few answers. A plan made around you.</span><button class="btn small" onclick="beginSetup()">Finish my setup →</button></div>':''}<section class="today-coach"><div>${mascotPortrait(currentMascot(),'tiny')}<div><span class="game-label">YOUR NEXT SMALL STEP</span><h3>${train?'A gym day, made simple.':'A little recovery goes a long way.'}</h3><p>${train?`Your ${state.profile.duration}-minute ${state.profile.days>=4?'upper/lower':'full-body'} session is ready.`:'Today is a recovery day in your schedule. Rest or comfortable movement both count.'}</p></div></div><button class="btn small" onclick="${train?'startSession()':'recoveryCheckIn()'}">${train?(active?'Resume session →':'Open my workout →'):'Recovery check-in ☾'}</button><small>${days.map(i=>['Sun','Mon','Tue','Wed','Thu','Fri','Sat'][i]).join(' · ')} · <button class="text-button" onclick="beginSetup()">Adjust schedule</button></small></section>${missing.length?`<div class="notice">Your selected equipment has no ${missing.join(' / ')} movement in this starter library. Your workout uses the available movements; add suitable equipment in My plan to expand coverage.</div>`:''}`}
// Extra plant-based choices keep the starter meal planner usable for vegan profiles.
meals.push({id:8,name:'Banana & peanut butter oats',tag:'Breakfast',diet:'Vegan',allergens:['Gluten','Peanuts'],time:10,img:'oats.jpg',ingredients:[[5,70],[7,120],[10,20]],steps:['Cook the oats with water according to the packet.','Slice the banana and add it to the warm oats.','Stir in the measured peanut butter. Use water to adjust the texture.']},{id:9,name:'Apple & peanut butter snack',tag:'Snack',diet:'Vegan',allergens:['Peanuts'],time:5,img:'oats.jpg',ingredients:[[14,180],[10,25]],steps:['Wash and slice the apple.','Serve with the measured peanut butter as a dip.']});
const healthProviders=[{id:'apple',icon:'♥',name:'Apple Health',label:'iPhone / Apple Watch',explain:'Apple Health needs an iPhone companion app and your permission for live sharing. This browser cannot read your Health app directly.',url:'https://developer.apple.com/health-fitness/'},{id:'samsung',icon:'S',name:'Samsung Health',label:'Galaxy / Android',explain:'Live Samsung Health access needs an Android companion app with permission. No native Forma app is connected to this website yet.',url:'https://developer.samsung.com/health/data/overview.html'},{id:'android',icon:'G',name:'Google Fit / Android Health',label:'Android / Health Connect',explain:'Android on-device health access needs a companion app through Health Connect. Google Fit APIs are supported through the end of 2026; new work should use Health Connect or the Google Health API. Neither is configured here yet.',url:'https://developer.android.com/health-and-fitness/health-connect/migration/fit'}];
function healthState(){state.health=state.health||{};state.health.records=state.health.records||[];return state.health}
function healthSources(){return [...new Set(healthState().records.map(r=>r.source))]}
function preferredHealthSource(){let h=healthState();return healthSources().includes(h.preferred)?h.preferred:healthSources()[0]||''}
function todayHealth(){let h=healthState();return h.records.find(r=>r.date===today()&&r.source===preferredHealthSource())}
function healthSummary(){let r=todayHealth(),has=healthState().records.length;return `<section class="health-mini"><div><span class="game-label">YOUR EVERYDAY WELLBEING</span><h3>${r?'Your day, at a glance.':has?'Your health journal is ready.':'Your movement story belongs here, too.'}</h3><p>${r?esc(r.source)+' · imported or manually logged data':has?'No entry for today from your selected source.':'Import an export or log a daily check-in. Phone apps are not connected yet.'}</p></div><div class="health-mini-stats"><span><b>${r?.steps!=null?n(r.steps).toLocaleString():'–'}</b><small>steps</small></span><span><b>${r?.sleep_minutes!=null?(r.sleep_minutes/60).toFixed(1)+'h':'–'}</b><small>sleep</small></span><span><b>${r?.active_minutes!=null?n(r.active_minutes):'–'}</b><small>active min</small></span></div><button class="text-button" onclick="go('health')">Health apps & journal ↗</button></section>`}
function healthApps(){let h=healthState(),source=preferredHealthSource(),records=h.records.filter(r=>r.source===source).sort((a,b)=>b.date.localeCompare(a.date));return pageTitle('YOUR PHONE. YOUR CHOICE.','Your health story, together.','Keep your movement and recovery context alongside your gym adventure.')+healthSummary()+`<div class="notice"><b>Live connections are not active in this website.</b> Apple Health, Samsung Health and Android Health Connect require native phone access. Choosing a provider below saves a preference only. Imports and manual entries work now and stay on this device.</div><div class="provider-cards">${healthProviders.map(p=>`<article class="card provider-card"><span class="provider-icon provider-${p.id}">${p.icon}</span><div><h3>${p.name}</h3><small>${p.label}</small></div><span class="status-off">Not connected</span><p>${p.explain}</p><button class="btn secondary" onclick="providerDetails('${p.id}')">Connection options ↗</button>${h.platform===p.id?'<small class="selected-source">Your preferred phone app</small>':''}</article>`).join('')}</div><section class="card health-import-card"><div class="section-head"><div><span class="game-label">WORKS ON THE WEBSITE TODAY</span><h2 style="margin-top:9px">Bring your own health export.</h2></div><span class="pill">Local import</span></div><p class="muted">Import daily CSV data from a health export, or an Apple Health export.xml file. Review the mapping and preview before anything is saved. This is a one-time import, not live synchronization.</p><div class="import-actions"><label class="file-pick"><span>↥ Choose CSV or Apple XML</span><input type="file" accept=".csv,.xml,text/csv,application/xml,text/xml" onchange="readHealthFile(this.files[0])"></label><button class="btn secondary" onclick="manualHealthEntry()">+ Manual check-in</button></div><details class="optional-details"><summary>Which files and data can I use?</summary><p>CSV imports let you choose the date, steps, sleep, active-minutes and weight columns. Use daily totals when possible. Apple XML imports read supported step-count, exercise-minute, sleep and body-mass records, and let you pick a single source. Extract export.xml from the Apple Health export ZIP before selecting it.</p><p>Limits: 5 MB CSV or 15 MB XML. No ZIP import. Apple XML raw step samples may differ from the totals in Apple Health because devices can overlap. Sleep intervals are merged within the selected source. Each date/source is saved once; later imports update its mapped fields.</p><p>Imported values do not automatically change your body profile, nutrition targets, workout weights or XP. No diagnoses are made from this data.</p></details></section><section class="card"><div class="section-head"><h2>Your health journal</h2>${source?`<select class="source-picker" aria-label="Health data source" onchange="healthState().preferred=this.value;save();render()">${options(healthSources(),source)}</select>`:''}</div>${records.length?`<div class="health-table-wrap"><table class="history"><thead><tr><th>Date</th><th>Steps</th><th>Sleep</th><th>Active</th><th>Weight</th></tr></thead><tbody>${records.slice(0,30).map(r=>`<tr><td>${r.date}</td><td>${r.steps==null?'–':n(r.steps).toLocaleString()}</td><td>${r.sleep_minutes==null?'–':(r.sleep_minutes/60).toFixed(1)+'h'}</td><td>${r.active_minutes==null?'–':n(r.active_minutes)+'m'}</td><td>${r.weight_kg==null?'–':r.weight_kg.toFixed(1)+'kg'}</td></tr>`).join('')}</tbody></table></div><small>Showing the latest ${Math.min(30,records.length)} dates from ${esc(source)}. Sources are displayed separately to avoid adding the same activity twice.</small>`:'<div class="empty">Your journal starts with your first import or check-in.</div>'}</section><div class="notice">Google account integration is deferred. A future native app can request health permissions by data type. No provider tokens, phone permissions or cloud uploads are being requested here.</div>`}
function providerDetails(id){let p=healthProviders.find(p=>p.id===id);openModal(`<span class="game-label">${p.name.toUpperCase()} / CONNECTION OPTIONS</span><h2 style="margin-top:15px">Your permission comes first.</h2><span class="status-off">Not connected · native companion needed</span><p class="muted" style="margin-top:18px">${p.explain}</p><div class="notice">For this web version, you can import a compatible export or log a check-in. Saving this preference does not authorize or start a sync.</div><div class="toolbar"><button class="btn" onclick="healthState().platform='${p.id}';save();closeModal();render();toast('Preference saved. No health connection was created.')">Use ${p.name} as my preference</button><button class="btn secondary" onclick="closeModal();manualHealthEntry()">Log a check-in</button></div><a target="_blank" rel="noopener" class="text-button" href="${p.url}">Official integration information ↗</a>`)}
function validHealthDate(v){if(!/^\d{4}-\d{2}-\d{2}$/.test(v))return false;let d=new Date(v+'T12:00:00Z');return !isNaN(d.getTime())&&d.toISOString().slice(0,10)===v&&v<=today()}
function healthValue(value,key){if(value===''||value==null)return null;let n=Number(String(value).replace(/,/g,''));let max={steps:200000,sleep_minutes:1440,active_minutes:1440,weight_kg:500}[key];return Number.isFinite(n)&&n>=0&&n<=max?n:null}
function upsertHealth(rows,source){let h=healthState(),count=0;for(let row of rows){if(!validHealthDate(row.date))continue;let data={};for(let k of ['steps','sleep_minutes','active_minutes','weight_kg']){let v=healthValue(row[k],k);if(v!=null)data[k]=v}if(!Object.keys(data).length)continue;let idx=h.records.findIndex(r=>r.date===row.date&&r.source===source),record={...(idx>=0?h.records[idx]:{}),...data,date:row.date,source,importedAt:new Date().toISOString()};if(idx>=0)h.records[idx]=record;else h.records.push(record);count++}h.preferred=source;save();return count}
function manualHealthEntry(){openModal(`<span class="game-label">YOUR DAILY WELLBEING</span><h2 style="margin-top:15px">A little check-in.</h2><form onsubmit="saveManualHealth(event)"><div class="fields"><label class="full">Date<input id="healthDate" type="date" required max="${today()}" value="${today()}"></label><label>Steps<input id="healthSteps" type="number" min="0" max="200000" step="1"></label><label>Sleep · hours<input id="healthSleep" type="number" min="0" max="24" step="0.1"></label><label>Active minutes<input id="healthActive" type="number" min="0" max="1440" step="1"></label><label>Weight · kg · optional<input id="healthWeight" type="number" min="0" max="500" step="0.1"></label></div><p class="muted" style="font-size:12px;margin-top:15px">Fill only the values you want to record. These entries won’t change your training weights, XP or nutrition targets.</p><button class="btn" type="submit">Save check-in ✓</button></form>`)}
function saveManualHealth(e){e.preventDefault();let row={date:$('#healthDate').value};for(let [key,id,mul]of [['steps','healthSteps',1],['sleep_minutes','healthSleep',60],['active_minutes','healthActive',1],['weight_kg','healthWeight',1]]){let value=$('#'+id).value;if(value!=='')row[key]=+value*mul}let count=upsertHealth([row],'Manual check-in');if(!count){toast('Add at least one valid value and date.');return}closeModal();render();toast('Health check-in saved')}
let healthImport=null;
function parseCSV(text){let rows=[],row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++}else quoted=!quoted}else if(c===','&&!quoted){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(c=>c.trim()))rows.push(row);row=[];cell=''}else cell+=c}row.push(cell);if(row.some(c=>c.trim()))rows.push(row);if(quoted)throw Error('The CSV contains an unclosed quoted field.');return rows}
async function readHealthFile(file){if(!file)return;const xml=/\.xml$/i.test(file.name),csv=/\.csv$/i.test(file.name);if(!xml&&!csv){toast('Choose a .csv or .xml file, not a ZIP.');return}if(file.size>(xml?15:5)*1024*1024){toast(`Choose a smaller file: ${xml?15:5} MB maximum.`);return}try{let content=await file.text();if(xml){let doc=new DOMParser().parseFromString(content,'application/xml');if(doc.querySelector('parsererror'))throw Error('This XML file could not be read.');let all=[...doc.querySelectorAll('Record')];if(!all.length)throw Error('No Apple Health Record elements were found.');let types=['HKQuantityTypeIdentifierStepCount','HKQuantityTypeIdentifierAppleExerciseTime','HKQuantityTypeIdentifierBodyMass','HKCategoryTypeIdentifierSleepAnalysis'];let records=all.filter(r=>types.includes(r.getAttribute('type'))).map(r=>Object.fromEntries(['type','sourceName','startDate','endDate','value','unit'].map(k=>[k,r.getAttribute(k)||''])));healthImport={mode:'xml',records,sources:[...new Set(records.map(r=>r.sourceName||'Apple Health'))],filename:file.name};if(!records.length)throw Error('No supported step, exercise, sleep or weight records were found.')}else{let rows=parseCSV(content.replace(/^\uFEFF/,''));if(rows.length<2)throw Error('The CSV needs a header and at least one data row.');if(rows.length>20001)throw Error('Choose a CSV with no more than 20,000 data rows.');healthImport={mode:'csv',headers:rows[0],rows:rows.slice(1),filename:file.name}}showHealthMapping()}catch(e){toast(e.message||'That file could not be read.')}}
function showHealthMapping(){let f=healthImport;if(!f)return;if(f.mode==='xml'){openModal(`<span class="game-label">APPLE HEALTH / REVIEW IMPORT</span><h2 style="margin-top:15px">Pick one data source.</h2><p class="muted">${esc(f.filename)} · ${f.records.length.toLocaleString()} supported records. Choosing one source helps avoid counting your phone and watch data twice.</p><label>Source<select id="xmlSource" onchange="previewHealthImport()">${options(f.sources,f.sources[0])}</select></label><div class="notice">Steps are raw sample sums within this source and may differ from Apple Health’s daily display. Overlapping sleep intervals are merged. This import does not create a live connection.</div><div id="importPreview"></div><button class="btn" id="commitHealthImport" onclick="commitHealthImport()">Save reviewed data ✓</button>`)}else{let guesses={date:/date|day|time/i,steps:/step/i,sleep_minutes:/sleep/i,active_minutes:/active|exercise|duration/i,weight_kg:/weight|mass/i};openModal(`<span class="game-label">CSV / MATCH YOUR COLUMNS</span><h2 style="margin-top:15px">A quick check before importing.</h2><p class="muted">${esc(f.filename)} · ${f.rows.length.toLocaleString()} rows. Use daily totals when possible. Date values must begin with YYYY-MM-DD.</p><div class="fields"><label class="full">Label this source<select id="csvSource" onchange="previewHealthImport()">${options(['Samsung Health export','Google Fit / Android export','Other health CSV'],'Samsung Health export')}</select></label>${Object.entries(guesses).map(([key,re])=>{let match=f.headers.findIndex(x=>re.test(x));return `<label>${({date:'Date',steps:'Steps',sleep_minutes:'Sleep',active_minutes:'Active time',weight_kg:'Weight'})[key]} column<select id="map-${key}" onchange="previewHealthImport()"><option value="-1" ${match<0?'selected':''}>Not included</option>${f.headers.map((h,i)=>`<option value="${i}" ${match===i?'selected':''}>${esc(h||'Column '+(i+1))}</option>`).join('')}</select></label>`}).join('')}<label>Sleep unit<select id="sleepUnit" onchange="previewHealthImport()">${options(['Minutes','Hours'],'Minutes')}</select></label><label>Active-time unit<select id="activeUnit" onchange="previewHealthImport()">${options(['Minutes','Seconds'],'Minutes')}</select></label><label>Weight unit<select id="weightUnit" onchange="previewHealthImport()">${options(['Kilograms','Pounds'],'Kilograms')}</select></label></div><div class="notice">Rows on the same date update earlier rows for the same source, rather than adding overlapping measurements. Check the preview before saving.</div><div id="importPreview"></div><button class="btn" id="commitHealthImport" onclick="commitHealthImport()">Save reviewed data ✓</button>`)}previewHealthImport()}
function mergedMinutes(intervals){let sorted=intervals.filter(([a,b])=>Number.isFinite(a)&&Number.isFinite(b)&&b>a).sort((a,b)=>a[0]-b[0]);let total=0,start=null,end=null;for(let [a,b]of sorted){if(start===null){start=a;end=b}else if(a<=end)end=Math.max(end,b);else{total+=end-start;start=a;end=b}}if(start!==null)total+=end-start;return total/60000}
function mappedHealthRows(){let f=healthImport;if(!f)return{rows:[],source:''};if(f.mode==='xml'){let source=$('#xmlSource').value,byDate={},seen=new Set();for(let r of f.records){if((r.sourceName||'Apple Health')!==source)continue;let date=(r.type==='HKCategoryTypeIdentifierSleepAnalysis'?r.endDate:r.startDate).slice(0,10);if(!validHealthDate(date))continue;let key=[r.type,r.startDate,r.endDate,r.value].join('|');if(seen.has(key))continue;seen.add(key);let day=byDate[date]||(byDate[date]={date,sleepIntervals:[]});if(r.type==='HKQuantityTypeIdentifierStepCount'&&Number.isFinite(+r.value))day.steps=(day.steps||0)+ +r.value;if(r.type==='HKQuantityTypeIdentifierAppleExerciseTime'&&Number.isFinite(+r.value))day.active_minutes=(day.active_minutes||0)+ +r.value*(r.unit==='s'?1/60:1);if(r.type==='HKQuantityTypeIdentifierBodyMass')day.weight_kg=+r.value*(r.unit==='lb'?0.45359237:1);if(r.type==='HKCategoryTypeIdentifierSleepAnalysis'&&/Asleep/i.test(r.value))day.sleepIntervals.push([Date.parse(r.startDate),Date.parse(r.endDate)])}let rows=Object.values(byDate).map(d=>{if(d.sleepIntervals.length)d.sleep_minutes=mergedMinutes(d.sleepIntervals);delete d.sleepIntervals;return d});return{rows,source:'Apple Health · '+source}}let map=Object.fromEntries(['date','steps','sleep_minutes','active_minutes','weight_kg'].map(k=>[k,+$('#map-'+k).value]));if(map.date<0)return{rows:[],source:$('#csvSource').value};let rows=f.rows.map(r=>{let out={date:(r[map.date]||'').trim().slice(0,10)};for(let k of ['steps','sleep_minutes','active_minutes','weight_kg'])if(map[k]>=0){let raw=r[map[k]];if(raw!=null&&raw.trim()!==''){let value=Number(raw.replace(/,/g,''));if(k==='sleep_minutes'&&$('#sleepUnit').value==='Hours')value*=60;if(k==='active_minutes'&&$('#activeUnit').value==='Seconds')value/=60;if(k==='weight_kg'&&$('#weightUnit').value==='Pounds')value*=0.45359237;out[k]=value}}return out});return{rows,source:$('#csvSource').value}}
function previewHealthImport(){let {rows}=mappedHealthRows(),valid=rows.filter(r=>validHealthDate(r.date)&&['steps','sleep_minutes','active_minutes','weight_kg'].some(k=>healthValue(r[k],k)!=null));$('#importPreview').innerHTML=`<h3 style="margin-top:22px">Preview · ${valid.length.toLocaleString()} usable rows</h3><p class="muted" style="font-size:11px">${rows.length-valid.length} rows skipped for missing dates or usable values. Future dates are excluded.</p><div class="health-table-wrap"><table class="history"><thead><tr><th>Date</th><th>Steps</th><th>Sleep · min</th><th>Active · min</th><th>Weight · kg</th></tr></thead><tbody>${valid.slice(0,8).map(r=>`<tr><td>${r.date}</td>${['steps','sleep_minutes','active_minutes','weight_kg'].map(k=>`<td>${healthValue(r[k],k)==null?'–':Math.round(r[k]*10)/10}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="muted" style="font-size:11px">Only your selected valid values will be saved locally.</p>`;$('#commitHealthImport').disabled=!valid.length}
function commitHealthImport(){let {rows,source}=mappedHealthRows(),count=upsertHealth(rows,source);if(!count){toast('No valid records were found. Check your mapping.');return}healthImport=null;closeModal();go('health');render();toast(`${count} health rows saved to this device.`)}
const cleanNavGroups=[{name:'Daily',links:[['today','◫','Today'],['workout','⌁','Workout'],['nutrition','◉','Food diary'],['quests','✦','Quests'],['games','▦','Pocket arcade']]},{name:'Explore',links:[['library','▤','Exercises'],['recipes','♧','Recipes'],['progress','↗','Progress']]},{name:'Your space',links:[['shop','◈','Camp & shop'],['health','♡','Health apps'],['mascots','☺','Mascots'],['profile','⚙','My plan'],['account','◎','Account & sync']]}];
function buildNavigation(){return cleanNavGroups.map((group,i)=>i===0?`<div class="nav-group"><span class="nav-group-label">${group.name}</span>${group.links.map(navLink).join('')}</div>`:`<details class="nav-group nav-fold" ${group.links.some(l=>l[0]===view)?'open':''}><summary>${group.name}<span>⌄</span></summary>${group.links.map(navLink).join('')}</details>`).join('')}
function navLink([id,icon,name]){if(id==='account')return '<button class="nav-account" onclick="showAccount()"><span>◎</span>Account & sync</button>';return `<a href="#${id}" class="${view===id?'active':''}" ${view===id?'aria-current="page"':''}><span>${icon}</span>${name}</a>`}
function renderAreaNavigation(){let area=['workout','library'].includes(view)?'train':['nutrition','recipes'].includes(view)?'fuel':['quests','games','shop','mascots'].includes(view)?'play':'today';$('#areaNav').innerHTML=[['today','Today','today'],['workout','Train','train'],['nutrition','Fuel','fuel'],['quests','Adventure','play']].map(([route,name,id])=>`<a href="#${route}" class="${id===area?'active':''}">${name}</a>`).join('');$('#bottomNav').innerHTML=[['today','◫','Today'],['workout','⌁','Train'],['nutrition','◉','Fuel'],['quests','✦','Quests']].map(([id,icon,name])=>`<a href="#${id}" class="${view===id?'active':''}"><span>${icon}</span>${name}</a>`).join('')+`<button aria-label="Open all navigation" onclick="toggleSidebar()"><span>☰</span>More</button>`}
function toggleSidebar(force){let open=typeof force==='boolean'?force:!document.body.classList.contains('nav-drawer-open');document.body.classList.toggle('nav-drawer-open',open);$('.nav-toggle')?.setAttribute('aria-expanded',String(open))}
function missionState(){let g=gaming();g.missions=g.missions||{};g.missions[today()]=g.missions[today()]||{};return g.missions[today()]}
function isRecoveryMission(){let ms=missionState();return ms.mode?ms.mode==='recovery':!(state.schedule?.days||suggestedDays(state.profile.days)).includes(new Date().getDay())}
function trainingMissionStatus(){let ms=missionState(),saved=state.sessions.some(s=>s.date===today());return {warmup:!!ms.warmup,saved,finish:!!ms.finish,complete:!!ms.warmup&&saved&&!!ms.finish}}
function dailyMissionCard(){let ms=missionState(),rest=isRecoveryMission(),q=dailyQuests().find(q=>q.id==='move'),t=trainingMissionStatus(),steps=rest?[{done:!!ms.restPlan,title:'Choose your recovery',sub:ms.restPlan||'Rest, a comfortable walk, or gentle mobility.',action:'chooseRecoveryPlan()'},{done:!!ms.energy,title:'Check in with yourself',sub:ms.energy||'How is your energy today?',action:'chooseEnergy()'},{done:!!gaming().recovery[today()],title:'Save your recovery day',sub:'Acknowledge the break you’re taking.',action:'finishRecoveryMission()'}]:[{done:t.warmup,title:'Warm up',sub:'Easy movement, then light practice sets.',action:"markMissionStep('warmup')"},{done:t.saved,title:'Train & save your session',sub:t.saved?'Your session is saved.':'Log the sets you actually do. Short sessions count.',action:'startSession()'},{done:t.finish,title:'Finish your check-in',sub:'A quick check-out after your session.',action:'finishTrainingMission()'}];let count=steps.filter(s=>s.done).length;return `<section class="daily-focus quiet-card" id="dailyMission"><div class="mission-eyebrow"><span class="kicker">TODAY’S MAIN MISSION</span><span class="reward-chip">40 XP · ◈ 20 ${inlineTip('rewards')}</span></div><div class="daily-focus-heading"><div><h2>${rest?'Recover with intention.':'A good gym visit.'}</h2><p>${rest?'A lighter day is part of your plan.':'Three clear steps. Go at your own pace.'}</p></div><div class="mission-ring" style="--done:${count/3*100}%"><span>${count}/3</span></div></div><ol class="mission-step-list">${steps.map((s,i)=>`<li class="${s.done?'step-done':''}"><span class="step-number">${s.done?'✓':i+1}</span><div><b>${s.title}</b><small>${s.sub}</small></div><button class="${s.done?'step-complete':'step-action'}" aria-label="${s.done?'Review: ':'Do step '+(i+1)+': '}${s.title}" onclick="${s.action}">${s.done?'Done':'Open →'}</button></li>`).join('')}</ol><div class="daily-focus-footer">${q.claimed?'<span class="collected-label">✓ Mission reward collected</span>':q.done?'<button class="btn" onclick="claimQuest(\'move\')">Collect 40 XP + 20 coins ✦</button>':`<button class="btn" onclick="${steps.find(s=>!s.done)?.action||'startSession()'}">${rest?(count===0?'Choose my recovery →':'Continue my check-in →'):(t.warmup?(t.saved?'Finish my check-in →':active?'Resume workout →':'Start my workout →'):'Start with a warm-up →')}</button>`}<button class="text-button" onclick="switchMissionMode()">${rest?'Make this a gym day':'Take a recovery day instead'}</button></div></section>`}
function switchMissionMode(){missionState().mode=isRecoveryMission()?'training':'recovery';save();render()}
function markMissionStep(step){openModal(`<span class="kicker">STEP 1 / WARM UP</span><h2 style="margin-top:12px">Ease into your session.</h2><p>Start with 5–8 minutes of comfortable movement, then rehearse your first exercise with a light load.</p><details class="fold-panel"><summary><span>What counts?</span><span>View ideas</span></summary><div class="fold-body">An easy walk or cycle, comfortable joint movements, and lighter practice sets. Choose movements that feel comfortable for you.</div></details><button class="btn" style="margin-top:18px" onclick="missionState().warmup=true;save();closeModal();render();toast('Warm-up checked. Your next step is ready.')">I’ve warmed up ✓</button>`)}
function finishTrainingMission(){if(!state.sessions.some(s=>s.date===today())){toast('Save your workout first, then finish your check-in.');go('workout');return}openModal(`<span class="kicker">FINAL STEP / CHECK OUT</span><h2 style="margin-top:12px">You showed up.</h2><p>Take a moment to settle after your session. A few minutes of easy movement can help you transition, if comfortable.</p><button class="btn" onclick="missionState().finish=true;save();closeModal();render();celebrate();toast('Session check-out saved. Collect your mission reward.')">My session is finished ✓</button>`)}
function chooseRecoveryPlan(){openModal(`<span class="kicker">RECOVERY / STEP 1</span><h2 style="margin-top:12px">What fits today?</h2><div class="choice-stack">${['Full rest','A comfortable walk','Gentle mobility'].map(t=>`<button class="btn secondary" onclick="missionState().restPlan='${t}';save();closeModal();render()">${t}</button>`).join('')}</div><small>Pick an intention. You can change it later.</small>`)}
function chooseEnergy(){openModal(`<span class="kicker">RECOVERY / STEP 2</span><h2 style="margin-top:12px">How’s your energy?</h2><div class="choice-stack">${['Low energy','Feeling steady','Feeling bright'].map(t=>`<button class="btn secondary" onclick="missionState().energy='${t}';save();closeModal();render()">${t}</button>`).join('')}</div>`)}
function finishRecoveryMission(){let ms=missionState();if(!ms.restPlan){chooseRecoveryPlan();return}if(!ms.energy){chooseEnergy();return}gaming().recovery[today()]=true;save();render();celebrate();toast('Recovery check-in saved. Your reward is ready.')}
function compactQuest(q){let done=q.claimed,ready=q.done;let sub=q.id==='move'?(isRecoveryMission()?'Recovery check-in':'Warm up · save session · check out'):q.id==='learn'?'Guide + light practice':'Log one meal';return `<div class="compact-quest ${done?'is-done':''}"><span class="compact-quest-icon">${done?'✓':q.icon}</span><div><b>${q.name}</b><small>${done?'Reward collected':sub}</small></div><button class="${ready&&!done?'quest-claim-small':'quiet-link'}" ${done?'disabled':''} onclick="${ready&&!done?`claimQuest('${q.id}')`:q.id==='move'?"go('today')":q.id==='learn'?"go('library')":"diaryDate=today();showFoodForm()"}">${done?'✓':ready?'Claim':'+ '+q.xp+' XP ↗'}</button></div>`}
const guideBeforeCleanup=showExercise;showExercise=function(k){guideBeforeCleanup(k);$('#modalContent').insertAdjacentHTML('beforeend',`<div class="practice-check"><h3>Try it, then check it off.</h3><p>Rehearse the movement with bodyweight or a light load, if it feels comfortable.</p><button class="btn" onclick="recordPractice(${k})">I tried a light practice set ✓</button></div>`)};
function recordPractice(k){let g=gaming();g.practice=g.practice||{};g.practice[today()]=g.practice[today()]||[];if(!g.practice[today()].includes(k))g.practice[today()].push(k);save();closeModal();go('quests');render();toast('Practice checked. Your quest reward is ready.')}
const helpContent={rewards:{title:'A little reward for real progress.',body:'Every 200 XP unlocks a level. Save sets and finish quests to earn XP; claim completed quests to collect their coins. Set XP is capped at 10 sets per day. Games don’t award workout XP or coins.'},quests:{title:'Do the action. Then collect.',body:'Main mission: warm up, save a workout, and complete the check-out, or save a recovery check-in. Practice quest: open a guide and confirm you tried a light practice set. Fuel quest: log a meal. Completed quests show a Claim button. Weekly quests and milestones have their own tabs.'},weight:{title:'Which weight should I enter?',body:'Use kilograms per dumbbell, total barbell weight, or the machine’s stack setting. Use 0 for bodyweight. Start light and choose a load that lets you keep control; height and body weight do not determine the right lifting load.'},rir:{title:'“Reps left” means effort.',body:'How many more good repetitions could you have done? About 2–3 is a useful starting point. It is optional to log. End a plank before posture breaks down; you can leave this field blank for holds.'},privacy:{title:'Your progress, your choice.',body:'Guest progress stays on this device. Google sign-in lets you opt into Firebase cloud saving, including your profile, diary, health records and progress. Each account has its own private save. Export a backup anytime. Live phone-health connections are not active.'},games:{title:'A small pause between sets.',body:'Play while stationary during a rest break. Each game lasts at most 20 seconds and ends when your workout rest timer ends. Stop whenever you want. Games only record personal bests; they do not award training XP or coins.'}};
function showHelp(topic){let h=helpContent[topic]||helpContent.privacy;openModal(`<span class="kicker">A LITTLE CONTEXT</span><h2 style="margin-top:15px">${h.title}</h2><p class="muted" style="font-size:14px;line-height:1.8">${h.body}</p><button class="btn secondary" onclick="closeModal()">Got it</button>`)}
function showContextHelp(){showHelp(view==='games'?'games':['workout','library'].includes(view)?'weight':['today','quests'].includes(view)?'quests':view==='shop'?'rewards':'privacy')}
function inlineTip(topic){let h=helpContent[topic],id='tip-'+uid();return `<span class="inline-help"><button type="button" class="help-dot" aria-label="${h.title}" aria-expanded="false" aria-controls="${id}" onclick="toggleTip(this)">?</button><span class="inline-tooltip" id="${id}" role="note" hidden>${h.body}</span></span>`}
function toggleTip(button){let tip=button.nextElementSibling,open=tip.hidden;document.querySelectorAll('.inline-tooltip').forEach(t=>{t.hidden=true;t.previousElementSibling.setAttribute('aria-expanded','false')});tip.hidden=!open;button.setAttribute('aria-expanded',String(open));if(open){let r=button.getBoundingClientRect(),w=Math.min(280,window.innerWidth-24);tip.style.width=w+'px';tip.style.left=Math.max(12,Math.min(r.left,window.innerWidth-w-12))+'px';tip.style.top=Math.min(r.bottom+8,window.innerHeight-tip.offsetHeight-12)+'px'}}
document.addEventListener('click',e=>{if(!e.target.closest('.inline-help'))document.querySelectorAll('.inline-tooltip').forEach(t=>{t.hidden=true;t.previousElementSibling.setAttribute('aria-expanded','false')})});document.addEventListener('keydown',e=>{if(e.key==='Escape'){toggleSidebar(false);document.querySelectorAll('.inline-tooltip').forEach(t=>{t.hidden=true;t.previousElementSibling.setAttribute('aria-expanded','false')})}});
function applyProgressiveDisclosure(){if(!['recipes','profile','shop','health'].includes(view))return;let notes=$('#app').querySelectorAll(view==='health'?'.provider-card>p':'.notice');for(let note of notes){if(note.closest('details'))continue;let fold=document.createElement('details');fold.className='inline-details';let sum=document.createElement('summary');sum.textContent=view==='health'?'How this connection works':view==='recipes'?'Diet filters & nutrition notes':view==='profile'?'Plan details':'Details';note.replaceWith(fold);fold.append(sum,note)}}
let currentGame=null,gameInterval=null;
function gameBest(kind){return state.gameScores?.[kind]?.best||0}
function games(){return pageTitle('POCKET ARCADE','A small break. A little play.','Two quick games for rest breaks, while you’re stationary.',`<button class="help-dot large-help" aria-label="How rest-break games work" onclick="showHelp('games')">?</button>`)+`<div class="games-grid"><article class="quiet-card game-card"><div class="game-art memory-art"><span>★</span><span>☾</span><span>☾</span><span>★</span></div><span class="kicker">MEMORY MATCH</span><h2>Find the pairs.</h2><p>Flip cards and match six pairs in 20 seconds.</p><span class="game-best">Personal best: ${gameBest('memory')} / 6 pairs</span><button class="btn" onclick="startMiniGame('memory')">Play memory match →</button></article><article class="quiet-card game-card"><div class="game-art focus-art"><i></i><i>✦</i><i></i><i></i><i></i><i></i></div><span class="kicker">CATCH THE SPARK</span><h2>A little focus.</h2><p>Tap the spark as it moves. Stop whenever you like.</p><span class="game-best">Personal best: ${gameBest('focus')} sparks</span><button class="btn" onclick="startMiniGame('focus')">Play catch the spark →</button></article></div><details class="fold-panel"><summary><span>Rest timer & scoring</span><span>How it works</span></summary><div class="fold-body"><p>Games last at most 20 seconds and finish when the workout rest timer ends. In an active workout, start a rest break before playing. They only record a personal best, with no workout XP or coins.</p><p>Keep the phone down during a lift. The game is optional and can be stopped at any time.</p></div></details>`}
function openArcadePicker(){openModal(`<span class="kicker">YOUR REST BREAK</span><h2 style="margin-top:14px">A little play?</h2><p class="muted">Stay stationary. Your game ends when rest is over.</p><div class="choice-stack"><button class="btn secondary" onclick="startMiniGame('memory')">★ Memory match · 20 seconds</button><button class="btn secondary" onclick="startMiniGame('focus')">✦ Catch the spark · 20 seconds</button></div><button class="text-button" onclick="closeModal()">Just rest instead</button>`)}
function shuffleCards(){let cards=['⚡','★','●','▲','◆','☾'].flatMap(s=>[s,s]);for(let i=cards.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[cards[i],cards[j]]=[cards[j],cards[i]]}return cards}
function startMiniGame(kind,createRest=false){if(!['memory','focus'].includes(kind))return;stopMiniGame();if(active&&!restEnd&&!createRest){openModal(`<span class="kicker">REST BEFORE YOU PLAY</span><h2 style="margin-top:14px">Ready for a break?</h2><p class="muted">Games belong between sets. Start a 60-second rest break, or return to your workout.</p><button class="btn" onclick="startMiniGame('${kind}',true)">Start rest & play →</button> <button class="btn secondary" onclick="closeModal();go('workout')">Back to workout</button>`);return}if(createRest)startRest(60);let duration=restEnd?Math.min(20000,restEnd-Date.now()):20000;if(duration<2000){toast('Rest is almost over. Save the game for your next break.');return}currentGame={id:uid(),kind,start:Date.now(),end:Date.now()+duration,restBound:!!restEnd,running:true,score:0,cards:shuffleCards(),flipped:[],matched:[],locked:false,target:Math.floor(Math.random()*9)};openModal(`<div class="game-session"><div class="game-session-top"><span class="kicker">${kind==='memory'?'MEMORY MATCH':'CATCH THE SPARK'}</span><b id="gameTime" aria-label="Seconds remaining">${Math.ceil(duration/1000)}s</b></div><h2>${kind==='memory'?'Find the matching pairs.':'Tap the spark.'}</h2><p class="muted">${kind==='memory'?'Flip two cards. Remember what you see.':'A relaxed little focus game.'}</p><div class="game-score-line"><b id="gameScore">0 ${kind==='memory'?'pairs':'sparks'}</b><span>${currentGame.restBound?'Linked to your rest timer':'20-second round'}</span></div><div id="gameBoard" class="${kind==='memory'?'memory-board':'spark-board'}"></div><button class="btn secondary" style="width:100%;margin-top:20px" onclick="finishMiniGame('Round stopped')">Stop game</button></div>`);renderGameBoard();gameInterval=setInterval(gameTick,150)}
function renderGameBoard(){let g=currentGame;if(!g?.running||!$('#gameBoard'))return;let focused=document.activeElement?.closest?.('#gameBoard');if(g.kind==='memory')$('#gameBoard').innerHTML=g.cards.map((s,i)=>{let open=g.flipped.includes(i)||g.matched.includes(i);return `<button class="memory-tile ${open?'flipped':''} ${g.matched.includes(i)?'matched':''}" aria-label="Card ${i+1}${open?', '+s:''}" ${g.matched.includes(i)||g.locked?'disabled':''} onclick="flipMemory(${i})">${open?s:'?'}</button>`}).join('');else{$('#gameBoard').innerHTML=Array.from({length:9},(_,i)=>`<button class="spark-tile ${g.target===i?'spark-live':''}" aria-label="${g.target===i?'Tap the spark':'Empty tile'}" ${g.target===i?'':'disabled'} onclick="tapSpark(${i})">${g.target===i?'✦':'·'}</button>`).join('');if(focused)$('#gameBoard .spark-live')?.focus()}$('#gameScore').textContent=g.score+' '+(g.kind==='memory'?'pairs':'sparks')}
function flipMemory(i){let g=currentGame;if(!g?.running||g.kind!=='memory'||g.locked||g.matched.includes(i)||g.flipped.includes(i))return;g.flipped.push(i);if(g.flipped.length===2){let [a,b]=g.flipped;if(g.cards[a]===g.cards[b]){g.matched.push(a,b);g.score++;g.flipped=[];renderGameBoard();if(g.score===6)finishMiniGame('All pairs found!')}else{g.locked=true;let id=g.id;renderGameBoard();setTimeout(()=>{if(currentGame?.id===id&&currentGame.running){currentGame.flipped=[];currentGame.locked=false;renderGameBoard()}},650)}}else renderGameBoard()}
function tapSpark(i){let g=currentGame;if(!g?.running||g.kind!=='focus'||g.target!==i)return;g.score++;let next;do{next=Math.floor(Math.random()*9)}while(next===i);g.target=next;renderGameBoard()}
function gameTick(){let g=currentGame;if(!g?.running)return;if(g.restBound&&(!restEnd||Date.now()>=restEnd)){finishMiniGame('Rest is done.');return}let sec=Math.max(0,Math.ceil((g.end-Date.now())/1000));if($('#gameTime'))$('#gameTime').textContent=sec+'s';if(sec===0)finishMiniGame('Round complete.')}
function finishMiniGame(reason='Round complete.'){let g=currentGame;if(!g?.running)return;g.running=false;clearInterval(gameInterval);gameInterval=null;state.gameScores=state.gameScores||{};let old=state.gameScores[g.kind]||{best:0,plays:0};state.gameScores[g.kind]={best:Math.max(old.best,g.score),plays:old.plays+1};save();openModal(`<div class="game-result">${mascotPortrait(currentMascot(),'tiny')}<span class="kicker">${reason}</span><h2>${g.score} ${g.kind==='memory'?'pairs matched':'sparks caught'}</h2><p class="muted">Personal best: ${gameBest(g.kind)}${g.kind==='memory'?' / 6 pairs':''}</p><p class="game-no-xp">Just for fun. Your workout progress stays separate.</p><div class="choice-stack"><button class="btn" onclick="closeModal();go('${active?'workout':'games'}')">${active?'Back to my workout →':'Back to the arcade →'}</button><button class="text-button" onclick="closeModal()">Done for now</button></div></div>`)}
function stopMiniGame(){clearInterval(gameInterval);gameInterval=null;if(currentGame)currentGame.running=false;currentGame=null}
document.addEventListener('visibilitychange',()=>{if(document.hidden&&currentGame?.running)finishMiniGame('Paused while you were away.')});

function updateAccountChrome(){let b=$('#accountButton');if(b){let a=window.formaAccount;b.textContent=a?.user?'◎':'Sign in';b.setAttribute('aria-label',a?.user?'Account and sync: '+a.status:'Sign in with Google')}}
function accountSummary(){return `<div class="setup-shortcut"><span>◎ Account & progress</span><button class="btn small secondary" onclick="showAccount()">${window.formaAccount?.user?'Manage sync':'Sign in with Google'} ↗</button></div>`}
function showAccount(){toggleSidebar(false);if(window.formaAccount)window.formaAccount.open();else openModal('<h2>Account & sync</h2><p>Connecting to Google sign-in…</p><button class="btn secondary" onclick="closeModal()">Keep using Forma</button>')}
window.formaProgress={
 snapshot:()=>JSON.stringify({state,active}),
 defaults:()=>JSON.stringify({state:normalizeProgress(),active:null}),
 cached:(owner)=>{try{let value=localStorage.getItem(owner?'forma-user-'+owner:'forma-v1');return value?JSON.stringify({state:JSON.parse(value),active:JSON.parse(localStorage.getItem(owner?'forma-active-'+owner:'forma-active')||'null')}):null}catch{return null}},
 apply:(payload,owner='')=>{let x=JSON.parse(payload);if(!x.state||!x.state.profile||!Array.isArray(x.state.sessions))throw Error('Invalid progress backup');progressOwner=owner;state=normalizeProgress(x.state);active=x.active||null;restEnd=0;$('.timer')?.remove();stopMiniGame();setupDraft=null;setupStep=0;if(state.onboarding?.complete&&location.hash==='#setup')location.hash='today';gaming();localStorage.setItem(progressKey(),JSON.stringify(state));localStorage.setItem(activeKey(),JSON.stringify(active));if(exercises.length)render()},
 refresh:()=>{if(exercises.length)render()},
 toast,openModal,closeModal,esc,updateAccountChrome
};
import('./firebase-account.js').catch(()=>{window.formaAccount={user:null,status:'Connection unavailable',changed(){},open(){openModal('<h2>Sign-in is unavailable right now.</h2><p>Your device progress is safe. Check your internet connection, then reload to retry Google sign-in.</p><button class="btn secondary" onclick="closeModal()">Keep using Forma</button>')}};updateAccountChrome()});
